window.__SUMMARY_PARTS__=window.__SUMMARY_PARTS__||[];window.__SUMMARY_PARTS__.push([{"i":66000,"as":"针对直接海水电解中电极腐蚀及传统阴离子保护策略在活化过程晶格退化或运行中阴离子脱附的问题，研究通过电沉积-阳极氧化法合成了非晶-晶体混合NiFeCoCr阳极，具有垂直双层结构。阳极氧化过程中Cr的部分牺牲性浸出形成非晶β-NiOOH相表层，暴露丰富活性位点增强OER性能。该阳极在500 mA cm⁻²电流密度下实现超过15000小时的超稳定海水氧化，为沿海和岛屿地区可再生能源大规模利用提供方案。","scd":{"b":7.0,"i":5.0,"r":5.0,"d":7.0,"t":6.0},"kp":["电极[NiOOH基阳极]: 双层非晶-晶体混合结构","制备工艺: 电沉积-阳极化法","应用[海水电解]: 超稳定性，克服阴离子保护策略的晶格降解/脱附问题"]},{"i":66001,"as":"针对水处理与资源提取方法能耗高、效率低和环境影响的挑战，研究开发了基于可持续连续组装变形(CAM)方法制备的水凝胶中空纤维。该方法实现非平衡分级组装，可对构象结构及物理化学属性进行协同调控，从而有效管理流体和分子相互作用。这种自组织设计原则为水驱动能源技术提供了整体性创新路径，应对污染治理、能源和资源提取等关键需求。","scd":{"b":6.0,"i":4.0,"r":4.5,"d":6.0,"t":5.5},"kp":["中空纤维[水驱动能源]: 结构与物理化学性质空间协同调控，实现高效流体管理与分子相互作用"]},{"i":66002,"as":"金属光催化剂可绕过半导体带隙限制利用低能近红外(NIR)光子进行CO₂转化，但其均匀静电势限制电荷分离与CO₂吸附活化。研究提出电荷极化策略：在金属相NiCo₂S₄中协同引入硫空位(Sv)与Au单原子。优化后的AuSA/Sv-NiCo₂S₄光催化剂在无牺牲剂条件下，NIR光照下活性较原始NiCo₂S₄提升64倍，CO和CH₄生成速率分别达102等高水平，实现高效近红外CO₂光还原。","scd":{"b":7.0,"i":4.0,"r":5.0,"d":7.0,"t":6.0},"kp":["光催化策略[金属光催化剂]: 电荷极化(表面物种协同掺杂)突破均匀静电势限制，实现高效近红外CO₂光还原","优势: 绕过传统半导体带隙限制，利用低能NIR光子"]},{"i":66003,"as":"益生菌的功能效果高度依赖其在肠道内的空间定位。研究开发了一种食品级微凝胶递送平台，以不同几何形状的玉米芯纳米纤维素为构筑单元，实现益生菌的可编程肠道释放。由于拓扑结构和力学性能差异，球形纳米纤维素微凝胶(CNSM)在回肠崩解，而棒状微凝胶(CNRM)则保持完整直至到达结肠后破裂释放。分子动力学模拟支持了两种微凝胶结构稳定性的差异，实现了肠道区域特异性益生菌递送。","scd":{"b":6.0,"i":3.5,"r":4.5,"d":6.5,"t":5.5},"kp":["微凝胶递送平台[肠道益生菌]: 玉米芯纳米纤维素构建，不同几何形貌实现肠道区域特异性程序化释放","属性: 可持续、食品级"]},{"i":66004,"as":"粘附水凝胶面临界面粘附与内聚强度此消彼长的固有矛盾。研究提出一种基于木质素介导儿茶酚化学和水合盐相变的粘附水凝胶，在1 V电刺激诱导结晶下实现界面粘附与内聚强度的协同增强。非晶态时水凝胶柔软且对多种基底呈温和粘附；电刺激诱导相变使内聚强度显著提升，皮肤表面界面粘附提高8–40倍，超过3000 J m⁻²。研究阐明了不同基底上的粘附增强机制，适用于可穿戴电子器件界面。","scd":{"b":6.5,"i":3.5,"r":4.5,"d":6.5,"t":5.5},"kp":["电刺激[水凝胶结晶]: 1 V触发相变结晶","机制: 木质素介导儿茶酚化学+盐水合物相变，界面粘附与内聚强度协同增强"]},{"i":66005,"as":"肿瘤缺氧、免疫抑制微环境及缺乏时空精准激活共同限制当前癌症治疗。研究报道了智能纳米复合材料G&Ru@CuS，通过四重顺序逻辑门控产生局部RNS/ROS风暴：(i)胞内ROS降解缩酮交联聚合物门卫，暴露中空CuS核；(ii)肿瘤酸性pH(6.5–6.8)和高GSH触发Cu²⁺、NO供体GSNO及NO响应线粒体靶向光敏剂前药Ru1从可降解CuS支架释放；(iii)Cu²⁺催化GSNO产NO；(iv)NO与Ru1反应生成Ru2，实现耐缺氧光动力癌症免疫治疗。","scd":{"b":8.0,"i":2.0,"r":5.0,"d":7.0,"t":6.0},"kp":["纳米复合材料: G&Ru@CuS（四层顺序逻辑门控RNS/ROS风暴）","逻辑门控机制: 细胞内ROS降解巯基酮交联聚合物门卫，暴露中空CuS核","肿瘤酸性pH触发: 6.5–6.8"]},{"i":66006,"as":"研究考察了c轴取向Mn₃Sn薄膜及其与Pt等构成的异质结中的磁有序与超快自旋输运。温度依赖的磁光克尔效应测量证实，在奈尔温度附近簇八极矩发生热激活翻转，同时保持以面内为主的磁有序。但在异质结结构中观察到明显的室温铁磁特征，包括增强的克尔旋转和面外磁化。系统磁强测量研究揭示了界面处形成混合界面层，为理解非共线反铁磁体界面自旋输运及其在超快自旋电子学中的应用提供依据。","scd":{"b":7.5,"i":3.0,"r":5.0,"d":6.0,"t":6.0},"kp":["材料体系: 非共线反铁磁体Mn₃Sn薄膜及与Pt异质结构","c轴取向薄膜: 热激活八极矩开关发生在奈尔温度附近"]},{"i":66007,"as":"水性锌碘电池受锌负极界面不稳定和多碘化物穿梭两种耦合失效机制限制。研究以分子偶极矩和LUMO能级为关键描述符，系统筛选44种氨基酸和二肽，发现L-肌肽(LC)兼具最高偶极矩和适中LUMO能级。LC的两性离子多中心电荷分布驱动其在锌界面的持久多齿吸附，抑制析氢反应，通过晶面选择性钝化引导(101)取向沉积，形成无枝晶锌负极，实现安时级稳定锌碘电池。","scd":{"b":7.0,"i":6.0,"r":6.0,"d":8.0,"t":7.0},"kp":["电池体系: 水系锌碘(Zn─I₂)电池","筛选范围: 44种氨基酸和二肽，以分子偶极矩和LUMO能量为描述符","最优添加剂: L-肌肽（LC），兼具最高偶极矩与双功能抑制机制"]},{"i":66008,"as":"物理储备计算（PRC）是边缘智能系统中处理高维时空数据的高能效范式，但连续输入信号与硬件有限动态范围之间的量化失配限制了其部署。传统二进制时分复用抗噪性强，但需要冗长脉冲序列，导致高延迟和过早物理饱和；多值模拟编码提升信息密度，却易引起状态重叠、缺乏物理量化边界。针对这一物理-信息权衡问题，研究提出了饱和约束信息容量（SCIC）框架，以忆阻器为基础，在信息密度与物理饱和约束之间取得平衡，用于时序信息处理。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":6.0},"kp":["技术范式: 基于忆阻器的物理储备池计算（PRC）","提出框架: 饱和约束信息容量框架，解决连续输入信号与硬件有限动态范围的量化失配问题"]},{"i":66009,"as":"该文关注数据中心的快速扩张对电力系统和规划流程带来的挑战。随着数据中心规模迅速增长，其用电需求对电网运行构成压力，现有规划过程难以跟上扩张速度。文章指出需要在电力系统与数据中心规划之间加强协调，以应对这一快速发展带来的基础设施与能源供给问题。","scd":{"b":2.0,"i":6.0,"r":4.0,"d":3.0,"t":6.0},"kp":[]},{"i":66010,"as":"LGBTQIA+气候科学家长期以来在社会和工作场所遭遇压迫与歧视。文章指出气候科学领域存在包容性不足的问题，并提出了一系列具体行动建议以提升气候科学的包容性。作者强调这些建议需要更多数据支撑，以推动性别与性少数群体在气候科学领域的公平参与。","scd":{"b":0.5,"i":1.0,"r":3.0,"d":1.0,"t":4.0},"kp":[]},{"i":66011,"as":"风速或太阳能发电量的快速下降可能使电力系统来不及做出响应。相关研究在全球范围内对这些事件进行了制图分析，并预测在气候变化背景下，此类事件（闪发能源干旱）的持续时间可能增加。这一发现凸显了电力系统面对可再生能源出力骤降时的脆弱性，对电网调度和应对策略具有重要警示意义。","scd":{"b":5.0,"i":6.0,"r":4.0,"d":5.0,"t":7.0},"kp":[]},{"i":66012,"as":"闪发能源干旱指风能和太阳能发电快速下降并随后持续处于低水平的现象，可能对电力系统运行构成潜在挑战。研究人员发现，气候变化可能加剧此类事件，包括风力、太阳能以及两者复合形式。研究强调了气候变化背景下可再生能源出力剧烈波动风险的增加，对电力系统规划和运行具有重要意义。","scd":{"b":6.5,"i":5.0,"r":6.0,"d":7.0,"t":7.0},"kp":["关键结论: 气候变化可能加剧风电、光伏及复合型闪发能源干旱事件"]},{"i":66013,"as":"","scd":null,"kp":[]},{"i":66014,"as":"一篇题为《堵塞与连通》的报道，探讨堵塞与连通（Jammed and connected）相关的主题，正文内容简短未提供更多细节。","scd":{"b":1.0,"i":1.0,"r":2.0,"d":1.0,"t":4.0},"kp":[]},{"i":66015,"as":"研究提出一种可生物吸收的镁-三氧化钼纸基电池，在生理条件下可输出1.84 V电压，使用后可自行降解。该平台在猪模型中得到验证，可为电池辅助的RFID药物依从性追踪和基于胶囊的胃电刺激提供电力。该成果为免取出的生物电子医学器件奠定了基础，适用于瞬态可摄入生物电子器件。","scd":{"b":8.0,"i":6.0,"r":6.0,"d":8.0,"t":7.0},"kp":["电池类型: 可生物吸收镁-三氧化钼纸基电池","输出电压[生理条件]: 1.84 V","降解特性: 使用后可降解，无需回收","验证模型: 猪模型，用于RFID用药依从性追踪和胶囊式胃电刺激"]},{"i":66016,"as":"碱基间隙开关是一类新型生物传感器，利用基因中工程化的间隙来调控转录过程，从而使蛋白质表达依赖于目标DNA的浓度。这一机制将蛋白质生产与特定DNA目标的存在直接关联，为疾病感知提供了强大工具，可用于检测疾病相关DNA并据此调控蛋白表达。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":4.0,"t":6.0},"kp":["碱基间隙开关[工作机制]: 通过基因工程间隙调控转录，蛋白质表达随靶DNA浓度变化"]},{"i":66017,"as":"多相催化研究长期受限于无法在工作条件下直接观测原子尺度结构变化。该研究结合工作条件电子显微镜与定量图像分析，以原子分辨率定量追踪了单个铂纳米颗粒在CO氧化过程中的三维结构演变，揭示了Taylor型与Langmuir型活性位点的共存及其动态相互作用，为深入理解多相催化机理提供了直接观测证据。","scd":{"b":8.5,"i":3.0,"r":6.5,"d":7.0,"t":6.0},"kp":["operando电镜[Pt纳米颗粒CO氧化]: 原子分辨率追踪三维结构演化","活性位点[单个Pt纳米颗粒]: Taylor型与Langmuir型位点共存并动态相互作用"]},{"i":66018,"as":"","scd":null,"kp":[]},{"i":66019,"as":"该研究提出通过集成多种归纳偏置模型来实现符合化学家习惯的逆合成预测。方法核心在于融合具有不同归纳偏置的多样化模型，以提升逆合成路线预测的效果，使其更贴近化学家的实际思维方式。","scd":{"b":6.0,"i":4.0,"r":5.0,"d":3.0,"t":5.0},"kp":["逆合成预测[方法]: 集成多种归纳偏置模型实现符合化学家习惯的逆合成"]},{"i":66020,"as":"","scd":null,"kp":[]},{"i":66021,"as":"","scd":null,"kp":[]},{"i":66022,"as":"研究团队开发了一种微型可食用电池，已在猪体内完成测试。该电池可为体内医疗设备供电，并在数月后在消化道内自行溶解，无需手术取出，为可降解的体内供电方案提供了新的可能。","scd":{"b":7.5,"i":6.0,"r":7.0,"d":4.0,"t":7.0},"kp":["可食用电池[猪体内测试]: 在消化道内数月后降解溶解"]},{"i":66023,"as":"","scd":null,"kp":[]},{"i":66024,"as":"人工智能系统已能生成科学假设、设计实验并分析数据，正在革新研究方式。但文章强调，人类仍需判断哪些结果真正有意义，AI共同科学家无法替代人在科学价值判断中的关键作用。","scd":{"b":5.0,"i":4.0,"r":4.0,"d":2.0,"t":5.0},"kp":["AI共同科学家[能力]: 可生成假设、设计实验和分析数据，人类仍需决策合理性"]},{"i":66025,"as":"","scd":null,"kp":[]},{"i":66026,"as":"一种新型表观遗传编辑技术问世，利用化学标签标记并关闭潜伏在宿主基因组中的乙型肝炎病毒DNA，从而清除病毒。该基因标记技术通过表观遗传手段抑制病毒基因，而并非直接切割DNA，为慢性乙肝治疗提供了新思路。","scd":{"b":8.0,"i":3.5,"r":6.5,"d":3.0,"t":7.0},"kp":["表观遗传编辑[乙肝病毒]: 利用化学标记沉默宿主基因组中的病毒DNA"]},{"i":66027,"as":"相变材料可在近等温相变过程中存储大量潜热，是理想的热管理材料。为实现系统级集成，该综述提出了一个多尺度设计框架，从分子和材料层面到模块和器件层面，对相变材料的热性能进行优化设计，为热管理系统开发提供指导。","scd":{"b":5.0,"i":5.0,"r":5.5,"d":5.0,"t":4.0},"kp":["相变材料[热管理]: 近等温相变中储存大量潜热","设计框架[相变材料]: 从分子、材料到模块、器件级别的多尺度热性能优化"]},{"i":66028,"as":"单一材质塑料产品由单一单体或共聚单体组合衍生的一种聚合物构成，有助于解决多材质塑料产品带来的可持续性问题。该综述讨论了面向单一材质化的工程工艺进展，以及单一材质化仍面临的技术挑战，为塑料可持续发展方向提供了系统梳理。","scd":{"b":5.5,"i":6.0,"r":5.5,"d":5.0,"t":4.0},"kp":["单一材质塑料[组成]: 由单一单体或共聚单体组合衍生的单一聚合物类型"]},{"i":66029,"as":"普鲁士蓝类似物存在由晶格水引起的容量衰减和安全隐患。该综述阐明了水与电化学之间的相互作用机制，总结了去除和阻断水分的策略，并讨论了该类材料规模化面临的挑战，为理解和调控普鲁士蓝类似物中的结晶水提供了系统性参考。","scd":{"b":5.0,"i":5.5,"r":5.5,"d":5.5,"t":4.0},"kp":["普鲁士蓝类似物[问题]: 晶格水导致容量衰减和安全隐患"]},{"i":66030,"as":"质子交换膜燃料电池（PEMFC）要求阴极催化剂兼具高铂利用率、高效传质和在严苛实际运行条件下的长期耐久性。然而，近期开发的铂基催化剂往往难以兼顾活性与耐久性。该研究通过石墨化碳膜打破了PEMFC阴极催化剂的活性-耐久性权衡，为高性能燃料电池催化剂设计提供新途径。","scd":{"b":6.5,"i":5.5,"r":5.0,"d":5.0,"t":5.0},"kp":["石墨化碳膜[PEMFC阴极催化剂]: 打破Pt基催化剂活性-耐久性权衡"]},{"i":66031,"as":"综述钠金属负极的基础认识、稳定化策略与未来发展前景，涉及钠离子电池负极技术方向。","scd":{"b":6.0,"i":3.0,"r":5.5,"d":4.0,"t":4.0},"kp":[]},{"i":66032,"as":"提出在分子量-分散度二维连续空间中导航的方法，实现聚合物分子量分布的确定性逆向设计。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":4.0,"t":4.0},"kp":["设计方法[分子量-分散度二维空间]: 确定性逆向设计"]},{"i":66033,"as":"富锂层状氧化物中的晶格氧氧化还原反应有望最大化电池容量，但受限于欠配位表面氧的化学不稳定性。在高电压驱动下，低对称性和悬挂键使表面氧O 2p带中心上移靠近费米能级，引发过早电子提取和不可逆产气。由于这些富电子表面氧是强路易斯碱，研究引入高极化率的大半径铯离子（Cs+），通过特定阳离子锚定构建局部电荷屏蔽层，淬灭其过度反应性，实现可逆阴离子氧化还原的稳定。","scd":{"b":7.5,"i":3.0,"r":5.5,"d":7.5,"t":5.0},"kp":["稳定化策略[富锂层状氧化物]: 阳离子电荷锚定屏蔽表面氧以稳定可逆阴离子氧化还原","失效机制[高压下欠配位表面氧]: O 2p带中心靠近费米能级，引发过早电子提取和不可逆产气"]},{"i":66034,"as":"聚阴离子正极中的高压Mn3+/Mn2+氧化还原反应有潜力提升电池能量密度并降低成本，但受制于缓慢的反应动力学和不对称Jahn-Teller畸变。研究报道了一种NASICON型正极Na3.85□0.15Mn1.35Fe1.5V0.15(PO4)2(P2O7)（NFMPP-V），通过钒取代重构Mn3+诱导的Jahn-Teller畸变，并将其与多价氧化还原过程耦合，实现了更高的能量密度和更快的反应动力学。值得注意的是，Na+迁移率随Jahn-Teller畸变增强而提高，与传统锰基正极相反，这源于有序的各向异性畸变。","scd":{"b":7.5,"i":4.0,"r":5.5,"d":7.5,"t":5.0},"kp":["正极材料[NASICON型混合磷酸盐]: Na3.85□0.15Mn1.35Fe1.5V0.15(PO4)2(P2O7)","改性策略[Jahn-Teller畸变]: 钒取代重构Mn3+诱导的Jahn-Teller畸变","氧化还原机制[高压]: Mn3+/Mn2+提升能量密度并降低成本"]},{"i":66035,"as":"负曲率纳米石墨烯常被视为环面体和schwarzite等新碳同素异形体的切片。该研究合成了包含152、228和304个碳原子、形似环面体或schwarzite的负曲率纳米环，并利用单晶X射线衍射解析了其中两个纳米环的结构，研究了它们与富勒烯在溶液中的超分子相互作用，并与相应宏观结构进行了比较。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.5,"t":4.5},"kp":["负曲率纳米环合成规模: 152、228、304个环状/schwarzite类碳原子","结构表征[两种纳米环]: 单晶X射线衍射解析"]},{"i":66036,"as":"近红外圆偏振发光（NIR CPL）材料在新兴光子技术中备受关注，但同时实现高发光效率和强手性光学活性仍具挑战。研究报道了一种晶格畸变策略，在无铅零维杂化金属卤化物中整合激子与手性光学功能。单晶分析与理论计算揭示了显著的手性晶格畸变，表现为大的连续手性度量（CCM）值、明显的偏心位移和孤立金属卤化物八面体的键长畸变。这种畸变晶格增强了电子-声子耦合，促进激发态结构重组，从而实现明亮的近红外圆偏振发光。","scd":{"b":7.0,"i":2.5,"r":6.0,"d":6.5,"t":4.5},"kp":["发光性能[无铅零维金属卤化物]: 亮近红外圆偏振发光","实现策略: 手性晶格畸变整合激子与手性光学功能"]},{"i":66037,"as":"研究人员在熔融无机盐中合成出无重金属的蓝光核壳胶体量子点，核心为2.1 nm的In1–xGaxP，外延包覆ZnS壳层并进行表面优化。通过计算模拟、结构和光谱研究对该材料进行了系统表征。该工作旨在解决蓝光QD-LED性能落后于红光和绿光器件的问题，为实现RGB全彩显示提供新型蓝光量子点材料，有望用于高色纯度、宽色域、高亮度和低成本溶液法制备的QLED显示。","scd":{"b":6.5,"i":5.0,"r":5.5,"d":6.5,"t":5.0},"kp":["量子点合成方法: 熔盐中合成胶体In1–xGaxP量子点","应用目标: 稳定性更优的蓝光QLED"]},{"i":66038,"as":"传统可充电电池依赖单离子或双离子机制：前者能量密度高但多价体系动力学受限，后者动力学好但持续消耗电解质而牺牲能量密度。本研究提出三元离子机制，通过三种离子物种的氧化还原反应相互匹配，并在正负极进行协调的多价金属离子交换，实现协同反应，克服能量密度与动力学之间的根本权衡。作为概念验证，作者构建了Al/eGr-PTO电池体系验证该机制的可行性。","scd":{"b":8.5,"i":3.0,"r":6.5,"d":6.0,"t":5.0},"kp":["电池机制: 三元离子机制，突破单离子(高能量密度/动力学受限)与双离子(动力学快/耗电解质)权衡"]},{"i":66039,"as":"经典金属-载体相互作用（MSI）通常需要高于500°C的高温处理，易导致金属烧结和过度包埋。本研究发现液态金属可在室温甚至低至-41°C下与可还原过渡金属氧化物实现MSI。在In/NiO模型体系中，室温接触下金属铟夺取NiO晶格氧，产生缺氧界面镍位点，增强CO2活化并从根本上改变CO2加氢反应路径——不同于镍基氧化物通常生成甲烷，液态金属衍生界面选择性促进CO生成。","scd":{"b":8.0,"i":4.5,"r":6.5,"d":7.5,"t":5.0},"kp":["金属-载体相互作用温度[液态金属]: 室温至-41 °C","模型体系: In/NiO","传统MSI实现温度: >500 °C"]},{"i":66040,"as":"氯化金与阳离子银联用是π酸介导有机反应中产生阳离子金的常用策略，但预合成的阳离子金往往不足以催化此类转化。本研究报道了含氯金纳米簇在保护配体壳层内形成Au–Cl–Ag反应活性中间体的罕见案例，实现炔烃的异构化/环化直接构建萘环。该串联反应发生在银活性位点上，并由罕见的炔烃向丙二烯异构化引发，为多取代β-萘酚衍生物提供了高效合成路线，也深化了对相关催化机理的认识。","scd":{"b":7.0,"i":2.5,"r":6.0,"d":6.5,"t":4.5},"kp":["催化策略[金纳米簇]: 含氯金纳米簇在配体壳层内形成Au–Cl–Ag活性中间体","应用[炔烃]: 直接合成β-萘酚醚"]},{"i":66041,"as":"传统铁电化合物设计通常局限于非中心对称的极性结构。本研究发现，即使在非极性质子导体Na2MnN(CN)4·3.25H2O中，长程离子位移也能产生巨大极化。该化合物结晶于非极性I2/a空间群，但铁电滞回和热刺激去极化电流测量证实其因传导质子而表现出极大极化。在298 K、80%相对湿度、0.01 Hz条件下，单晶沿[010]方向实现了438 mC cm–2的剩余极化，拓展了铁电材料设计的结构边界。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":7.0,"t":7.0},"kp":["晶体结构[Na2MnN(CN)4·3.25H2O]: 非极性I2/a空间群","极化机制[非极性质子导体]: 长程离子位移产生巨大极化"]},{"i":66042,"as":"荧光蛋白氧化型发色团成熟形成酪氨酸Cα═Cβ双键的机理尚不清楚。在光激活荧光蛋白PAmCherry1中，光激活前该双键尚未形成。研究利用X射线自由电子激光的串飞秒晶体学（SFX）捕获了未光激活PAmCherry1的无辐射损伤结构，显示咪唑啉酮环内发色团酪氨酸残基的sp3杂化Cα原子上共价结合一个氢过氧基团（占据率73%），周围独特的氢键网络稳定了这一高活性中间体，为揭示发色团成熟机理提供了直接结构证据。","scd":{"b":8.5,"i":2.0,"r":6.5,"d":7.5,"t":7.0},"kp":["成像技术[PAmCherry1结构解析]: 无X射线自由电子激光的串飞秒晶体学(SFX)","结构特征[光激活前PAmCherry1]: 酪氨酸Cα═Cβ双键尚未形成，捕获无辐射损伤结构"]},{"i":66043,"as":"本研究报道了一系列完全由非手性组分构成的非重叠双钉合嵌段型肽，包含α-α、310-310、α-310和310-α螺旋结构。尽管几何构型和氢键模式各异，相邻螺旋片段能高效通信，导致 exclusively 形成同手性(P,P)-和(M,M)-螺旋。颠倒α与310螺旋嵌段顺序使螺旋翻转速率产生5.5倍差异，表明嵌段序列控制P/M互变动力学，其中非重叠α-α结构表现出动力学稳定化效应，深化了对肽螺旋间动态相互作用的理解。","scd":{"b":7.0,"i":2.0,"r":5.5,"d":6.5,"t":7.0},"kp":["肽设计[双钉合嵌段肽]: 全部由非手性组分构成，含α-α、310-310、α-310、310-α螺旋架构","关键结论[相邻螺旋段]: 尽管几何与氢键模式不同仍能高效通讯，实现动力学稳定化对抗螺旋翻转"]},{"i":66044,"as":"本研究报道了以简单N-芳基胺引发剂实现芳炔与醛的直接交替共聚。N-芳基胺框架对抑制芳炔均聚竞争反应至关重要，并通过Smiles型重排路径促进选择性交替聚合。每个增长循环中中性N-芳基胺链端的再生，使通过扩环交替共聚制备嵌段共聚物和环状聚合物等复杂拓扑成为可能。所得聚合物中嵌入的醚键赋予其酸触发的可降解性。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.5,"t":7.0},"kp":["聚合方式[芳炔与醛]: N-芳基胺引发的直接交替共聚","催化机制[N-芳基胺框架]: 通过Smiles型重排途径抑制芳炔均聚，促进选择性交替聚合","链端特征[每个增长循环]: 中性N-芳基胺链端再生，可通过扩环交替聚合构建嵌段和环状聚合物"]},{"i":66045,"as":"镍催化芳基与烷基亲电体的交叉亲电偶联（XEC）是重要的合成方法，但机理路径复杂，难以预测特定亲电体组合的结果。已有假说认为芳基卤化物氧化加成速率与烷基自由基生成速率的\"速率匹配\"以及Ni(II)–Ar配合物的稳定性决定偶联产率。为定量探究，研究者开发了一种新型三齿单阴离子配体，可活化烷基和芳基氯化物并具有良好电化学行为，从而可测量相对速率常数，为用数据科学工具检验速率匹配概念提供了框架。","scd":{"b":6.5,"i":4.0,"r":5.0,"d":7.0,"t":6.5},"kp":["关键结论[镍催化交叉亲电偶联]: 芳基卤化物氧化加成速率与烷基自由基生成速率的匹配及Ni(II)–Ar配合物稳定性决定偶联产率"]},{"i":66046,"as":"铂比铱更丰富且耐腐蚀，但因自钝化绝缘PtO2膜的形成而未被用作酸性氧阳极。本研究通过将Pt纳米颗粒锚定在费米能级高于Pt的钽掺杂二氧化钛载体上，构建电子穿梭结缓解这一瓶颈。内置接触电势经Pt–O–Ta/Ti桥向Pt注入电子，并在高偏压下持续将析氧旁路电子引入Pt，抑制钝化α-PtO2层的形成。原位光谱证实Pt 5d占据得以保持，表面水吸附增强，实现耐酸性PEM电解水阳极。","scd":{"b":8.5,"i":5.0,"r":6.5,"d":8.0,"t":7.0},"kp":["阳极催化剂[酸性OER]: Pt纳米颗粒负载于Ta掺杂TiO2载体","设计机制[Pt/Ta-TiO2结]: 费米能级高于Pt的载体通过内置接触电势向Pt注入电子，缓解PtO2绝缘自钝化"]},{"i":66047,"as":"p型ZrCoSb基half-Heusler化合物因优异热稳定性和机械强度，是高温发电的候选热电材料，但传统变价掺杂效率有限，难以实现高简并载流子输运，功率因子受限，性能落后于p型ZrCoBi体系。本研究强调相图工程对提升其热电性能的关键作用，在实验相图指导下精确调控Co含量，同时增强了电子输运性能，为ZrCoSb基材料性能优化提供了组分设计策略。","scd":{"b":6.5,"i":4.0,"r":5.0,"d":7.0,"t":6.5},"kp":["材料体系[p型高温热电]: ZrCoSb基Half-Heusler化合物","性能瓶颈[传统异价掺杂]: 掺杂效率受限，阻碍高简并载流子输运与功率因子优化","改进策略[相界面工程]: 实现多能谷激活以提升热电性能"]},{"i":66048,"as":"双金属协同催化可突破单金属反应性的机理限制，但通常需要支撑配体，限制了催化剂形态与反应性。本研究报道了无配体支撑的Ni–Ga异金属体系，可将C(sp2)–F键转化为C(sp2)–Ga键，并能在双金属与三金属催化模式间动态切换以完成催化循环关键步骤。光谱、动力学、计算研究及关键中间体的定向分离表明，双金属Ni–Ga双烯烃配合物为催化静息态，并揭示了C–F活化相关的 turnover 限制过渡态。","scd":{"b":7.5,"i":2.5,"r":6.0,"d":7.0,"t":7.0},"kp":["催化体系[C(sp2)–F键镓化]: 无配体支撑的Ni–Ga异金属体系","机制特征[Ni–Ga体系]: 可在双金属与三金属催化物种间动态切换"]},{"i":66049,"as":"研究者合成了一系列基于手性8-氨基喹啉-2-羧酸的芳香低聚酰胺折叠体，长度最高约5 nm，并在螺旋一端引入巯基化喹啉单体以便固定于金基底。划痕原子力显微镜和偏振调制红外反射吸收光谱证实单层膜形成，厚度约1.1至5.4 nm，取决于低聚物长度。磁性导电原子力显微镜评估显示自旋选择信号随螺旋长度增加而增大，最高达约85%，表明可通过分子长度调控螺旋芳族低聚物的自旋过滤性能。","scd":{"b":6.5,"i":2.0,"r":5.5,"d":6.5,"t":6.5},"kp":["分子长度[手性螺旋芳酰胺低聚物]: 最长约5 nm","结构特征[螺旋体一端]: 引入硫醇化喹啉单体以固定于金基底","表征方法[自旋过滤性能]: 划痕AFM与PM-IRRAS确认组装"]},{"i":66050,"as":"本研究在局域高浓度电解质中引入与锂离子强、弱配位的共溶剂以改善锂金属电池循环性能。两类溶剂的协同相互作用促进接触离子对进入初级溶剂化壳层，并在锂金属负极和NMC811正极表面形成富氟界面层。优化电解质由双氟磺酰亚胺锂溶于强配位溶剂DME、弱配位溶剂F6DEE及稀释剂四氟乙基四氟丙基醚组成，通过调控溶剂化结构与界面化学提升电池循环稳定性。","scd":{"b":6.0,"i":6.0,"r":5.0,"d":7.5,"t":6.5},"kp":["电解液体系[锂金属电池]: 含强/弱配位共溶剂的局域高浓度电解液","正极材料: LiNi0.8Mn0.1Co0.1O2 (NMC811)","界面特征[Li负极与NMC811正极]: 溶剂化鞘中接触离子对促进富氟界面层形成"]},{"i":66051,"as":"阳离子无序岩盐（DRX）正极因高理论容量和丰富过渡金属（Mn、Ti、Fe）储量而备受关注，Li+经三维0-TM扩散通道网络传输，但锰基DRX正极常受结构不稳定和不可逆氧氧化困扰。本研究系统考察Li/TM化学计量比对Li0.9+xMn1.1–2xTixO2（x=0.2、0.3、0.4）正极电化学性能与退化行为的影响，发现Li、Mn、Ti间的化学计量平衡决定了主导氧化还原反应及后续结构演化。","scd":{"b":6.5,"i":3.0,"r":5.5,"d":7.0,"t":6.0},"kp":["正极类型: 锰基阳离子无序岩盐(DRX)","扩散机制: 三维0-TM渗流网络","挑战[循环过程]: 结构不稳定与不可逆氧氧化还原"]},{"i":66052,"as":"柔性碳电极钙钛矿太阳能电池低成本、可快速更新且易于集成，是弱光应用的候选技术，但其性能落后于金属电极器件，主要归因于缺乏高效的缓冲层/碳组合。本研究系统研究了两种典型阳极结构：以P3HT/NiOx或Spiro-OMeTAD作为空穴传输层，配合刮涂碳（B-C）或压制自支撑碳膜（P-C）阳极。综合表征表明，压制碳电极与空穴传输层的组合可改善界面接触，为高效柔性室内光伏器件的阳极缓冲层选择提供依据。","scd":{"b":5.0,"i":3.5,"r":4.5,"d":6.5,"t":6.0},"kp":["器件结构: 碳电极柔性钙钛矿太阳能电池","应用场景: 弱光室内光伏","性能瓶颈: 缓冲层/碳电极组合效率不足"]},{"i":66053,"as":"晶体管尺寸微缩加剧了集成电路功耗挑战，需要突破60 mV/dec热玻尔兹曼极限亚阈值摆幅的器件。本研究提出基于范德华异质结的冷源场效应晶体管，以单层硼锑化物（BSb）为源电极、硒化铟（InSe）为沟道。通过第一性原理DFT与量子输运模拟证明，该FET无需特意源掺杂即可实现本征冷源工作——BSb电极独特的能带结构充当天然能量过滤器，截断高能载流子注入，实现亚60 mV/dec的亚阈值摆幅。","scd":{"b":8.0,"i":2.5,"r":6.5,"d":7.5,"t":6.0},"kp":["亚阈值摆幅: 亚60 mV/dec","器件结构[BSb/InSe范德华异质结]: 冷源场效应晶体管(CS-FET)","沟道材料: 硒化铟(InSe)","源极材料: 单层硼锑(BSb)"]},{"i":66054,"as":"Hopfield网络为高能效联想存储提供了硬件友好框架，但器件间（D2D）变异性阻碍其在忆阻器交叉阵列中的可靠并行编程。本研究通过系统调控导电桥式随机存储器（CBRAM）中Ge–Te固体电解质的组分解决该瓶颈，确定Ge3.5Te1为最优组成，其特征参数的平均变异系数相比GeSe基器件最小。拉曼光谱显示该改善与以Ge为中心的四面体配位环境分布更窄相关，实现了高度均匀的GeTe基CBRAM及无选通器Hopfield联想网络中的并行Hebbian学习。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["器件类型: GeTe基导电桥随机存取存储器(CBRAM)","最优电解质组分: Ge3.5Te1","应用架构: 无选通器Hopfield型联想网络","关键特征: 电解质键合工程降低器件间(D2D)变异性"]},{"i":66055,"as":"本研究将SrCoO3–δ（δ=0.3–0.5）钙钛矿体系作为酶模拟物\"Perovzymes\"，其具有从六方到立方结构的丰富相图。研究考察了压力控制的缺氧正交相（SCO-1）与富氧四方相（SCO-16）之间相变对类酶活性的影响，发现氧化酶样活性对晶体结构转变呈现明显依赖性，证明晶体结构调控可影响类酶催化性能，为压力调控的相依赖活性无机酶模拟催化剂提供了范例。","scd":{"b":7.0,"i":2.5,"r":6.0,"d":7.0,"t":6.0},"kp":["催化材料: SrCoO3–δ (δ = 0.3–0.5)钙钛矿类酶催化剂","结构特征: 六方至立方相依赖催化活性","调控手段: 压力调控晶体结构"]},{"i":66056,"as":"利用水和氧光合成过氧化氢是分散式化学品制造的可持续途径，但受缓慢的水氧化反应限制。本研究报道蒽醌基共价有机框架（TpAQ）的碱触发酮式重构策略：在强碱性条件（pH=13）下，氢氧根离子诱导自发的烯醇-酮互变异构，生成酮式主导的框架，其电子结构和界面催化微环境得以重构。所得富酮式TpAQ可见光吸收拓宽、价带位置正移、电荷分离加速，显著增强水氧化动力学，实现从水和氧高效光合成H2O2。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["催化材料: 蒽醌基共价有机框架(TpAQ)","反应条件: 强碱性 pH = 13","策略[水和氧光合成H2O2]: 碱触发烯醇-酮互变异构重构","限速因素: 缓慢的水氧化反应"]},{"i":66057,"as":"针对激光3D打印对高质量粉末依赖且打印块体热电性能差的问题，研究采用激光定向能量沉积（L-DED）方法，通过优化打印参数，将不规则形状的p型Bi0.5Sb1.5Te3粉末成功打印成多晶块体。通过引入过量Te和Sb原子，一方面促进晶格平整化以增强载流子输运，另一方面通过原位形成多重缺陷加强声子散射，实现电输运与热输运的协同优化。该协同增强使打印的p型块体在高温下达到1.42的显著zT值，为复杂热电器件的增材制造提供了可行途径。","scd":{"b":6.0,"i":4.0,"r":5.0,"d":7.0,"t":6.0},"kp":["打印方法: 激光定向能量沉积(L-DED)","材料体系: p型Bi0.5Sb1.5Te3多晶块体","策略: 晶格平整化与缺陷工程协同提升热电性能"]},{"i":66058,"as":"防晒霜的白痕是由防晒膜光散射引起的皮肤可见泛白，是消费者涂抹量低于标注SPF所需的2 mg/cm²的主要原因。现有白痕量化方法依赖人体体内评分，标准体外SPF测量仅考虑紫外透射，无法区分吸收与反射。研究采用积分球反射光谱，测量了三种有机过滤型和三种无机过滤型防晒霜（UV过滤成分相近），发现反射可占离开皮肤的紫外光的30%，这一贡献未被基于透射的标准SPF测量明确捕捉，为防晒霜表征提供了新方法。","scd":{"b":4.0,"i":3.0,"r":4.5,"d":6.0,"t":5.0},"kp":["防晒霜标准厚度: 2 mg/cm2","测量方法: 积分球反射光谱","方法局限[传统体外SPF]: 仅测UV透射，混淆吸收与反射"]},{"i":66059,"as":"研究解耦了LiPF6、碳酸甲乙酯（EMC）和碳酸亚乙烯酯（VC）三种电解质组分在溶剂化结构及硅负极日历老化中的作用。通过改变各组分的摩尔分数并采用电压保持协议，提取了每种组分对硅负极日历寿命的贡献。结果显示，LiPF6浓度不影响日历老化，而增加EMC摩尔分数和降低VC摩尔分数会降低电极表面钝化性。日历寿命结果与分子动力学模拟得出的EMC配位数一致，表明内溶剂化壳层在日历老化机制中起作用；X射线光电子能谱数据进一步揭示了固体电解质界面的变化。","scd":{"b":5.5,"i":4.5,"r":5.5,"d":8.0,"t":6.0},"kp":["锂盐: LiPF6","溶剂: 甲基乙基碳酸酯(EMC)","添加剂: 碳酸亚乙烯酯(VC)","结论[硅负极日历老化]: LiPF6浓度不影响老化，EMC与VC摩尔分数分别起正向与负向作用"]},{"i":66060,"as":"富勒烯及其衍生物的抗菌性能高度依赖光照，限制了其生物医学应用。研究报道了一种由富勒醇与镓（Ga）组成的新型纳米粒子，对其形貌、化学结构进行了表征并阐明了组装机制。单个Fullerenol-Ga纳米粒子的平均直径为10–30 nm，富勒醇分子与Ga³⁺的组装过程通过静电吸附与配位交联的耦合机制实现。研究还系统考察了该纳米粒子在避光条件下的抗氧化活性、成骨性能和抗菌效果，表明其无需光照即可发挥多功能生物活性，是一种有前景的骨科植入物改性添加剂。","scd":{"b":5.5,"i":2.5,"r":5.0,"d":6.5,"t":5.5},"kp":["材料体系: 富勒醇-镓(Fullerenol-Ga)纳米粒子","组装机制: 静电-配位耦合交联","功能特性: 兼具抗氧化、成骨与抗菌活性","应用方向: 骨科植入物改性添加剂"]},{"i":66061,"as":"研究展示了一种用于AlGaN/GaN高电子迁移率晶体管（HEMT）近结热管理的复合晶体氮化铝（AlN）钝化层。120 nm厚的AlN薄膜由有序界面AlN区域和上部多晶覆盖层构成。时域热反射（TDTR）测量显示，复合AlN的有效跨面热导率为47.2 W/m·K，远高于氮化硅（SiNx）参考的2.58 W/m·K；其界面热阻为10.0 m²·K/GW，低于SiNx钝化界面的29.6 m²·K/GW。空间分辨振动电子能量损失谱（EELS）进一步表明界面处连接更紧密，证实该钝化层可显著提升GaN器件的散热性能。","scd":{"b":7.0,"i":5.0,"r":5.5,"d":7.5,"t":5.0},"kp":["复合氮化铝钝化层厚度: 120 nm","复合AlN有效跨面热导率[TDTR测量]: 47.2 W/m·K","AlN薄膜结构: 界面有序AlN区+上部多晶覆盖层","应用对象[AlGaN/GaN HEMT]: 近结热管理钝化层"]},{"i":66062,"as":"侧流免疫分析（LFIA）因低成本和简便性广泛用于即时诊断，但传统形式依赖主观目视判读，缺乏定量准确性和灵敏度。研究提出一个智能手机引导、人工智能增强的LFIA平台，结合合理设计的双模态纳米探针与设备端机器学习，用于裂谷热病毒（RVFV）的定量检测。该平台整合三项协同原则：先进磁性量子点纳米粒子（AQDs）将磁性内核与量子点壳层集成于单一标记中，同时提供比色和荧光信号并实现目标抗原的磁性预富集；多光源照明成像；以及设备端机器学习，实现智能定量诊断。","scd":{"b":5.0,"i":4.0,"r":5.0,"d":6.0,"t":5.0},"kp":["平台架构: 智能手机引导+AI增强的侧流免疫分析","探针: 双模态纳米探针+端侧机器学习","应用目标: RVFV定量检测"]},{"i":66063,"as":"仅选通器存储（SOM）在单一易失性阈值开关层中集成存储与选通功能，为高密度交叉阵列提供紧凑架构，其性能强烈依赖于硫系化合物网络中陷阱态的引入与分布。传统SOM材料常依赖含As或Te的硫系化合物进行陷阱态工程，但存在毒性、稳定性和集成挑战。研究报道了Sb掺杂Ge2Se3作为无As/无Te的SOM材料，考察了Sb诱导的陷阱态调制对低能耗和可靠运行的影响。纯Ge2Se3性能受限，Sb掺杂通过调制陷阱态实现了可靠的低能耗阈值开关与存储操作。","scd":{"b":7.0,"i":4.5,"r":6.0,"d":7.0,"t":5.0},"kp":["存储架构: 仅选通器存储","开关机制: 易失性阈值开关层","材料体系: 无As/Te的Ge2Se3","关键工艺: Sb诱导陷阱态调制"]},{"i":66064,"as":"双波长响应光致变色材料因时间-波长双重维度控制对信息安全的协同增强而备受关注。研究报道了一对手性离子氢键有机框架（R/S-iHOF-68），通过电荷辅助相互作用实现双波长响应光致变色。电子供体(1R/S,2R/S)-1,2-二苯基乙二胺与电子受体NDI衍生物相互作用，共同构筑二维超分子框架。在275 nm和365 nm照射下，R/S-iHOF-68晶体粉末表现出不同的光致变色行为，光生产色物种速率不同，可实现多形态先进信息存储与加密应用。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["材料体系: 手性离子氢键有机框架R/S-iHOF-68","光致变色特性: 双波长响应","框架结构: 二维超分子框架","应用: 多形态先进信息存储与加密"]},{"i":66065,"as":"声动力治疗（SDT）是一种具有深组织穿透优势的无创肿瘤治疗方法，但开发兼具良好稳定性的高效有机声敏剂仍具挑战。研究设计合成了含不同取代基（甲氧基、辛氧基、蒽和碘原子）的一系列aza-BODIPY衍生物（AB1–AB5），系统评估电子给体效应和重原子效应对声动力疗效的影响，以揭示构效关系。其中碘取代的aza-BODIPY（AB5）表现出最优的声动力性能，活性氧（ROS）生成能力增强。研究随后对其进行了封装，用于乳腺癌深组织声动力诊疗。","scd":{"b":5.0,"i":3.0,"r":4.5,"d":6.0,"t":5.0},"kp":["声敏剂: aza-BODIPY衍生物AB1–AB5","取代基设计: 甲氧基/辛氧基/蒽/碘原子","应用: 乳腺癌深组织声动力诊疗"]},{"i":66066,"as":"隐形眼镜因视野清晰、贴合舒适、美观隐形及兼容日常活动而在视力矫正中应用广泛，但传统镜片易被细菌定植，可引发眼部感染和角膜炎。研究设计并制备了基于多酸纳米酶的变色隐形眼镜，用于抗菌抗炎眼部治疗。镜片中的多酸纳米酶可有效催化分解过量活性氧，缓解氧化应激，同时抑制细菌生长繁殖。该镜片兼具光致变色和抗菌功能，为预防和治疗隐形眼镜相关的眼部感染提供了新策略。","scd":{"b":6.0,"i":3.5,"r":5.0,"d":6.0,"t":5.0},"kp":["隐形眼镜功能基元: 多酸纳米酶","功能: 光致变色+优异抗菌活性","应用: 预防细菌定植引起的眼部感染"]},{"i":66067,"as":"","scd":null,"kp":[]},{"i":66068,"as":"","scd":null,"kp":[]},{"i":66069,"as":"研究开发了超声激活的微针贴片（FCSP-MN），将FeSnO(OH)5/Cu2S异质结纳米粒子（FCS）与根皮素集成于pH响应的聚丙烯酸/聚乙烯吡咯烷酮微针尖端，用于局部肿瘤治疗。异质结形成促进界面电荷再分布，约1.942个电子从Cu2S转移至FeSnO(OH)5，并将速率决定步骤（类过氧化物酶）的能垒从2.38降至2.03 eV。由此，FCS增强了超声触发的单线态氧和羟基自由基生成、类过氧化物酶催化及谷胱甘肽耗竭，放大氧化应激。微针可高效穿透皮肤并响应酸性环境释药。","scd":{"b":6.0,"i":3.0,"r":4.5,"d":7.5,"t":5.0},"kp":["体系: 超声激活FeSnO(OH)5/Cu2S异质结微针贴片(FCSP-MN)","界面电荷转移[Cu2S→FeSnO(OH)5]: 约1.942个电子","限速类过氧化物酶步骤能垒: 由2.38降低(异质结形成)","载体: pH响应聚丙烯酸/聚乙烯吡咯烷酮微针"]},{"i":66070,"as":"研究构建了用于乳腺肿瘤线粒体靶向光热-化学联合治疗的分级超粒子：以透明质酸（HA）包覆Fe3O4超粒子，并共载阿霉素（DOX）与三苯基膦（TPP），即Fe3O4-DOX-TPP@HA SPs。作为Fe3O4纳米粒子的组装体，超粒子具有超顺磁性，可借助外加磁场实现初级肿瘤组织靶向；HA涂层通过结合CD44高表达的乳腺肿瘤细胞实现二级靶向。肿瘤细胞中高含量透明质酸酶进一步降解HA，释放药物至线粒体，实现光热与化疗协同治疗。","scd":{"b":5.0,"i":3.0,"r":4.0,"d":6.0,"t":5.0},"kp":["体系: HA包覆Fe3O4-DOX-TPP@HA超粒子","靶向性: 线粒体靶向(TPP)","疗法: 光热-化学联合治疗乳腺肿瘤","超粒子特性: Fe3O4纳米粒组装的超顺磁性"]},{"i":66071,"as":"糖尿病伤口治疗受多重因素阻碍，包括金黄色葡萄球菌生物膜（糖尿病伤口感染的主要病原体）、免疫反应失调和血管生成不足，而现有疗法未充分应对这些局部病理因素的复杂相互作用。研究报道了一种由氧化铈负载铱簇（Ir-CeO2）构成的杂化生物催化平台。该结构实现pH响应的活性氧（ROS）催化，使生物催化剂同时发挥抗菌和抗炎作用，共同促进糖尿病伤口愈合。Ir-CeO2表现出双重pH依赖的催化行为，在感染酸性微环境中协同对抗感染与炎症。","scd":{"b":6.5,"i":3.5,"r":5.0,"d":6.5,"t":5.0},"kp":["平台: 二氧化铈负载铱簇酶杂化生物催化体系","响应特性: pH响应","功能: 抗菌抗炎联合治疗糖尿病伤口"]},{"i":66072,"as":"加工引起的界面损耗限制了钙钛矿纳米晶发光二极管（PeLEDs）在显示相关器件面积上的性能，但相关工艺步骤很少在冠军器件报道之外获得统计置信的识别。研究将全无机CsPbBr3发光层与28 mm²有源区的重复因子设计研究相结合。采用苯丙胺（PPA）封端的纳米晶经室温改进配体辅助再沉淀法（MLARP）合成，以两步旋涂成膜并用约2.8 nm聚乙烯吡咯烷酮（PVP）中间层分隔，顶层沉积前进行温和真空处理。十三个架构中七个在两次制备中重复，获得84个器件中71个功能器件（84.5%良率），并通过2×2因子方差分析识别关键工艺因素，实现大面积高亮度。","scd":{"b":6.5,"i":4.5,"r":5.5,"d":7.0,"t":5.0},"kp":["有源区面积: 28 mm2","发光层: 全无机CsPbBr3钙钛矿纳米晶","配体: 苯丙胺(PPA)封端","合成方法: 室温改进配体辅助再沉淀法(MLARP)","研究方法: 复制因子设计统计研究"]},{"i":66073,"as":"研究首次报道了通过分子内SNAr（芳香亲核取代）实现催化N-杂环芳基化的通用方法，可用于合成高张力大环和中等尺寸杂联芳基阻转异构环及阻转肽。方法关键在于催化生成强碱，因为在非催化条件下所需环化反应存在困难。布朗斯特碱催化的取代反应常因离去基团碱性差导致转化率低，该方案中碱的再生不依赖pKa，而是依靠氟离子催化剂（路易斯碱）与有机硅烷（载碱亲电体）的反应。该协议适用范围广泛，涵盖多种杂环底物。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["合成方法[大环与中环杂联芳基阻转异构体]: 首例催化分子内N-杂环芳基化SNAr反应","反应关键[催化体系]: 催化生成强碱以实现高张力环化"]},{"i":66074,"as":"Mo-固氮酶的生物固氮是需要通过特化金属簇协调电子转移的复杂过程。NifEN是固氮酶催化组分NifDK的α2β2异源四聚体同源物，通常作为成熟支架，但因簇环境不完善仅表现出微量催化活性。研究系统改造NifEN以重建NifDK的结构特征，针对P→M簇电子传递链和活性位点M簇环境，构建了一系列变体，最终获得NifEN P/M_S2B，其恢复了P簇物种并优化了M簇配位位点及S2B相关带区。光谱分析证实了簇结构的重建，实现自组装固氮酶的功能增益。","scd":{"b":8.5,"i":2.0,"r":6.5,"d":6.0,"t":6.0},"kp":["NifEN催化活性[天然状态]: 仅痕量","NifEN结构[与NifDK关系]: α2β2四聚体同源物、成熟支架","工程策略[自组装固氮酶]: 重构NifDK结构特征，靶向P簇位点"]},{"i":66075,"as":"锡铅（Sn-Pb）混合钙钛矿太阳能电池在高效率叠层光伏中前景广阔，但器件运行中的大幅温度波动产生机械应力，叠加钙钛矿/空穴传输层（HTL）界面粘附不足，导致钙钛矿开裂和界面分层，阻碍空穴提取并损害长期稳定性。研究引入1,2-乙二膦酸（EDPA）作为界面分子桥重构钙钛矿与HTL的接触界面。EDPA末端膦酸基团同时锚定PEDOT:PSS并与钙钛矿配位，实现埋底界面重构，提升热机械稳健性，改善空穴提取并延长器件寿命。","scd":{"b":6.5,"i":5.0,"r":5.0,"d":7.0,"t":6.0},"kp":["界面工程方法[Sn–Pb钙钛矿/HTL埋底界面]: 双齿膦酸酯桥接重构","目标特性[Sn–Pb PSC]: 热机械稳健、抗裂纹与界面分层"]},{"i":66076,"as":"单原子取代是编辑分子结构的极精细手段，但此类微小原子级修饰如何传递到生物功能尚不清楚。研究建立了硒连接Tn糖肽的高效合成路线，与O连接和S连接对应物一起，实现MUC1糖肽抗原糖苷键处的系统性原子级编辑。表面等离子共振建立了清晰的抗原识别层级，并通过分子动力学模拟合理解释，经STD-NMR表位作图独立验证：O→S→Se取代微妙地重塑糖肽构象展示，同时保留5E5抗体的整体识别表位。这些结构明确的抗体进一步展示了差异化功能。","scd":{"b":7.0,"i":2.5,"r":6.0,"d":6.5,"t":6.0},"kp":["修饰策略[MUC1糖肽疫苗糖苷键]: 单原子O/S/Se取代编辑","表征手段[抗原结合]: 表面等离子体共振建立抗原识别等级差异"]},{"i":66077,"as":"研究阐明了在明确还原条件下氧化石墨烯（GO）水体系中金纳米粒子（AuNPs）的逐步形成机制。脉冲辐解揭示GO通过水合电子显著加速AuCl4⁻的还原，改变早期动力学；原位同步辐射小角X射线散射（SAXS）和时间分辨紫外-可见吸收光谱直接观察了AuNPs的成核与生长。Au(III)的还原先于GO的还原，新生Au簇通过与羧基的相互作用优先锚定在GO边缘，导致各向异性、尺寸受限的生长。研究揭示了GO在金纳米颗粒成核与生长中的关键作用。","scd":{"b":5.5,"i":2.5,"r":5.0,"d":7.0,"t":5.5},"kp":["生长机制[AuNPs/氧化石墨烯水体系]: GO加速水合电子还原AuCl4−，改变成核早期动力学","表征手段[AuNP形成过程]: 脉冲辐解+原位同步辐射SAXS"]},{"i":66078,"as":"COF异质结薄膜中光生载流子的宏观定向迁移通常受载流子随机扩散和界面结构无序的阻碍。研究首次报道了由晶格匹配的同网状COF（COF-366/COF-366-OH）构筑的序列可控Janus COF薄膜。紧密的界面组装与能级偏移诱导内建电场，驱动电子和空穴在整个薄膜内定向迁移至相对两侧。这种不对称电荷分布赋予薄膜两侧不同的氧化还原活性，通过简单翻转薄膜即可实现对氧化性和还原性气体的可切换、高灵敏检测，展示了Janus COF薄膜在气体传感中的应用潜力。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.5,"t":6.0},"kp":["薄膜结构[Janus COF]: 首次由晶格匹配COF-366/COF-366-OH序列控制构筑","载流子迁移机制[异质结薄膜]: 能级差诱导内建电场驱动定向迁移","应用[COF薄膜]: 可切换气体传感"]},{"i":66079,"as":"高电压钴酸锂（LCO）是高能量密度锂金属电池的重要正极材料，但需将充电截止电压提升至4.5 V以上才能充分释放其比能量潜力。深度脱锂会引发不可逆相变和界面副反应，其根源在于LCO表面本征脆弱。本研究提出表面键合分子集成（SMI）范式，通过多位点相互作用重构LCO表面，赋予其优异的电化学活性和结构稳定性。经合理优化筛选，确定单锂化肌醇磷酸（CPLi）为最优分子，其在Lewis酸碱相互作用驱动下可精确锚定于配位不饱和的Co3+位点。","scd":{"b":7.0,"i":5.5,"r":5.5,"d":6.5,"t":6.5},"kp":["充电截止电压[高比能LiCoO2]: >4.5 V","表面重构策略[高压LCO]: 表面键合分子集成(SMI)多位点相互作用"]},{"i":66080,"as":"传统大尺寸、结构明确的分子空腔通常依赖刚性共价骨架构建，结构适应性受限且合成复杂。本研究提出氢键编码的超分子策略，使结构最简的柔性单体自组装成可结合富勒烯的离散胶囊。该单体同时含有分子内和分子间氢键基序，可限制构象自由度、诱导环手性，并引导其受控自组装为寡聚或环状聚集体。光谱与晶体学分析表明，富勒烯客体诱导的自分类驱动形成同手性四聚体胶囊，具有高结合亲和力和独特的结构异构现象，X射线结构证实了组装体结构。","scd":{"b":6.0,"i":2.0,"r":5.5,"d":5.0,"t":5.5},"kp":["组装策略[大空腔超分子胶囊]: 氢键编码、结构最简柔性单体自组装","单体特征[环手性]: 分子内/间氢键限制构象自由并诱导环手性"]},{"i":66081,"as":"采用卤化物/硫化物双层电解质的全固态电池可结合卤化物的高氧化稳定性与硫化物的高还原稳定性，是实现高能量密度的可行途径，但卤化物–硫化物界面严重不相容导致界面持续退化并阻碍锂离子传输。不同于依赖包覆层或人工缓冲层的传统界面工程，本研究提出基于局部化学的本征相容性策略：对非晶卤化物电解质Li2O–TaCl5进行硫化处理，同时重构其短程配位化学与中程拓扑结构，富硫局部基序从根本上稳定了卤化物–硫化物界面并实现快速离子传输。","scd":{"b":7.5,"i":6.0,"r":5.5,"d":7.0,"t":6.5},"kp":["电解质构型[全固态电池]: 卤化物/硫化物双层电解质","卤化物优势[氧化稳定性]: 高","硫化物优势[还原稳定性]: 优","界面策略[卤化物–硫化物界面]: 局部阴离子化学亲和性调控，无需涂层/缓冲层"]},{"i":66082,"as":"熔点超过200°C的聚烯烃极为罕见，其合成通常依赖高位阻α-烯烃的聚合，对工业Ziegler–Natta催化剂和均相催化剂均具挑战性。吡啶基酰胺-Hf配合物是已知的高活性分子催化剂，能高效聚合位阻大的单体，如可将烯丙基三甲基硅烷（ATMS）聚合成熔点310°C、转换频率高的等规聚（烯丙基三甲基硅烷），但无法高效聚合乙烯基环己烷（VCH）和4,4-二甲基-1-戊烯（44DMP）等单体。本研究报道了一种新型合成策略，实现了此类高位阻单体的聚合。","scd":{"b":6.5,"i":5.0,"r":5.5,"d":6.0,"t":6.0},"kp":["熔点[先进超高熔点聚烯烃]: >200°C","催化剂[高活性聚合]: 吡啶胺-Hf配合物","单体示例[位阻烯烃聚合]: 烯丙基三甲基硅烷(ATMS)合成等规聚(ATMS)"]},{"i":66083,"as":"大气取水（AWH）依赖于在低相对湿度（RH）下呈S形吸附等温线的固体吸附剂。本研究对SIFSIX-3-Ni系列混合配位网络（HCNs）及一个新相关HCN家族进行评估，揭示其共享的协同化学吸附机制，但RH阈值和再生要求差异显著。SIFSIX-3-Ni家族的运行超出所需RH和再生温度范围，而四种M′FSIX-25-M类似物（M=Co2+、Ni2+；M′=Si4+、Ti4+）兼具低RH化学吸附和34–44°C低温再生能力。最优再生优化化学吸附剂ROC-1（TIFSIX-25-Ni）的预计取水产率约为3.5 L·(吸附剂·天)⁻¹。","scd":{"b":7.0,"i":4.0,"r":5.5,"d":6.5,"t":5.5},"kp":["吸附机制[SIFSIX-3-Ni/HCNs]: 共享协同化学吸附机制","吸附等温线[固体干燥剂]: S形多台阶低压相对湿度吸附","再生特性[M′FSIX-25-M]: 再生阈值低于SIFSIX-3-Ni族"]},{"i":66084,"as":"环糊精（CD）是超分子化学中广泛使用的主体分子，但其主动引导无机簇结构重组的能力尚少探索。本研究证明α-CD可在自组装过程中引导无机簇重组，合成出以往难以获得的偶氮苯功能化多金属氧酸盐（POM）准轮烷，其中大环不仅包封有机轴，还主导无机核心的结构演化。与α-CD配位后，平坦的砷酸根功能化{Mo6}簇重组为弯曲类似物，形成动态准轮烷组装体（1a@α-CD）；进一步精细调节pH可诱导CD介导的转化，生成反式组装结构。","scd":{"b":7.5,"i":2.5,"r":5.5,"d":6.0,"t":5.5},"kp":["α-环糊精[自组装过程]: 引导无机簇结构重组","合成策略[准轮烷]: 实现偶氮苯功能化多金属氧酸盐准轮烷","宿主作用[α-CD]: 包封有机轴并主导超分子组装"]},{"i":66085,"as":"Zintl相是无碲热电器件的关键材料。n型Zintl材料（如Mg3Sb2）性能优异，但p型材料受电子-声子耦合限制。本研究开发了高性能、低成本的p型CdSb基Zintl热电材料。研究发现熵工程可显著提高Cu在CdSb中的固溶度；在熵工程化的Cd0.5Zn0.5Sb中掺杂Cu提高了载流子浓度，更重要的是，Cu通过屏蔽电离杂质散射并增强[100]方向解理面上的共价键合，将载流子迁移率提升至约222 cm²V⁻¹s⁻¹，从而获得优异的热电性能。","scd":{"b":7.0,"i":4.0,"r":5.0,"d":7.0,"t":5.5},"kp":["热电材料[无碲p型]: Cd₀.₅Zn₀.₅Sb Zintl相基CdSb材料","改性策略[CdSb基Zintl]: 熵工程+Cu掺杂提升固溶度并解锁高性能","掺杂元素[Cd₀.₅Zn₀.₅Sb]: Cu掺杂"]},{"i":66086,"as":"混合氧化物低温氧化还原催化通常通过调节体相组成优化，但决定性化学过程发生在表面与次表面界面。本研究通过对Mn–Ce氧化物进行先真空退火、后低压O2处理的顺序处理，在基本保持萤石CeO2骨架的同时诱导近表面Mn富集。该重构提高了近表面含锰物种的丰度，改变了Mn–Ce–O界面的电子与氧化还原环境，促进氧活化和氧化还原循环。在耦合条件下，重构催化剂R-MnCe在100°C下实现95.5%的NOx转化率，并在200°C下实现氯苯的完全转化。","scd":{"b":6.5,"i":4.5,"r":5.0,"d":6.5,"t":5.5},"kp":["制备工艺[Mn-Ce氧化物]: 真空退火+减压O₂顺序处理诱导表面重构","重构效果[近表面]: Mn富集且基本保持萤石CeO₂骨架","催化性能[Mn-Ce氧化物]: 实现低温耦合氧化还原催化"]},{"i":66087,"as":"以可预测方式控制分子随机运动是功能分子系统发展的重大挑战。本研究展示了一种光驱动分子马达可通过远程空间位阻相互作用可逆调控布朗旋转。研究者将 overcrowded 烯烃马达集成于刚性三蝶烯骨架中，作为与炔基相连的蒽转子的可逆位阻门控。光异构化调节转子轴周围的空间环境，使体系在快速布朗旋转态和位阻受阻态之间切换。变温核磁共振谱显示，马达的一种热力学稳定状态下蒽单元绕炔基C─C≡C─C轴快速布朗旋转，另一种状态则旋转受阻，实现了对布朗旋转的光门控控制。","scd":{"b":8.0,"i":2.0,"r":5.5,"d":6.0,"t":5.5},"kp":["调控机制[布朗旋转]: 光驱动分子马达通过远程位阻作用可逆调控","结构设计[分子马达]: 拥挤烯烃马达嵌入刚性三蝶烯支架","门控方式[转子]: 光致异构化调制蒽转子周围位阻环境"]},{"i":66088,"as":"端粒重复序列RNA（TERRA）在采用ALT端粒延长途径的端粒酶阴性癌细胞端粒维持中发挥核心作用，但其RNA G-四链体（rG4）结构作为化学靶点仍研究不足。本研究报道了基于吲哚喹喔啉小分子骨架、结构导向选择性调控TERRA rG4的方法。生物物理分析证实其高亲和力和选择性结合；核磁与计算研究表明末端四分体堆叠是配体与TERRA rG4的主要结合模式。配体结合可破坏TERRA–TRF2相互作用，改变TERRA丰度，转录组分析揭示了对ALT通路的广泛影响。","scd":{"b":7.5,"i":3.0,"r":5.5,"d":6.5,"t":5.5},"kp":["靶向策略[TERRA rG4]: 吲哚喹喔啉类小分子支架选择性调控","结合特性[小分子-TERRA rG4]: 高亲和力和高选择性结合","作用机制[ALT端粒维持]: 小分子重编程TERRA RNA四链体"]},{"i":66089,"as":"在多环芳烃（PAHs）中掺杂多个硼及其他杂原子可产生多共振效应，获得极具前景的窄带发射体，但其合成困难制约发展。本研究报道采用甲氧基导向、无锂的一锅硼化路线，克级规模简便合成了新型四硼-氧键、氮集成PAH（QBO-1）及额外吡啶氮掺杂的衍生物（QBO-Py）。两种发射体均表现出超窄带紫光发射：在甲苯中半峰宽分别为7.4和8.6 nm，在OLED器件中分别为9.5和11.2 nm，QBO-1的电致发光结果代表了热活化延迟荧光的优异性能。","scd":{"b":7.0,"i":3.5,"r":5.0,"d":6.5,"t":5.5},"kp":["合成路线[硼化PAHs]: 甲氧基导向、无锂一锅硼化反应","分子结构[QBO-1]: 四硼-氧共价键+氮集成PAH","衍生物[QBO-Py]: 额外引入吡啶氮掺杂","发光性能[QBO系列]: 多共振效应实现超窄带热活化延迟荧光"]},{"i":66090,"as":"过硫化氢因其优良的生化亲核性和膜保护自由基清除能力受到关注，其形成的过硫自由基通过自复合终止自由基链反应生成多硫化物，但多硫化物如何被还原尚不清楚。本研究结合停流动力学测量与质谱分析，发现恶性疟原虫I型谷氧还蛋白模型蛋白PfGrx可快速还原谷胱甘肽三硫化物（GS3G）和四硫化物（GS4G），生成谷胱甘肽化PfGrx及相应的GSSH和GS3H。其二级速率常数≥10⁷ M⁻¹s⁻¹，甚至略高于谷胱甘肽的还原速率。","scd":{"b":6.5,"i":2.5,"r":5.0,"d":6.5,"t":5.5},"kp":["还原底物[PfGrx]: 快速还原谷氨酸过硫化物与多硫化物","研究方法[反应动力学]: 停流动力学+质谱联用","生化意义[过硫化物]: 优良亲核试剂与膜保护性自由基清除剂"]},{"i":66091,"as":"将有机分子普适、高效地转化为具有长余辉和均匀形貌的水相磷光纳米颗粒（PNPs）是材料化学的持久挑战。本研究报道一种通用原位硅烷化平台，通过氨基硅烷介导的\"桥\"将有机前驱体集成于硅基基质中，制备出单分散、尺寸可调（10~320 nm）的全色PNPs，发射覆盖蓝紫至红光。具有给电子特性的氨基硅烷不仅促进分子内电荷转移（ICT）态以增强系间窜越（ISC）效率，还促进硅烷化酸酐在硅框架内的封装，从而实现水相长余辉磷光。","scd":{"b":7.0,"i":4.0,"r":5.0,"d":6.5,"t":5.5},"kp":["制备平台[水性磷光纳米球]: 原位硅烷化通用平台","桥接机制[硅基基质]: 给电子氨基硅烷介导桥接","粒径调控[PNPs]: 10~320 nm，单分散可调","发射特性[PNPs]: 全彩色、长余辉水性磷光"]},{"i":66092,"as":"人形机器人复杂自主交互受限于传统传感硬件的复杂性和随机性，易失性忆阻器提供了有前景的仿生替代方案，但无序氧化物中不受控的离子动力学限制其性能。本研究报道二维SnS2中间层作为氧化物扩散型忆阻器中空位引导离子迁移的有效平台。在Ag/TaOx/SnS2/ITO异质结构中引入可调硫空位密度的溶液法SnS2层以调控导电丝形成：电偏压下SnS2的硫空位局部增强电场，为Ag+迁移提供确定性路径，实现稳定的扩散型忆阻行为和仿生伤害感受功能。","scd":{"b":7.5,"i":5.5,"r":5.5,"d":7.0,"t":5.5},"kp":["中间层材料[氧化物忆阻器]: 二维SnS₂","工作机制[扩散型忆阻器]: 空位引导离子迁移","器件应用[忆阻器]: 稳定扩散动力学并实现仿生伤害感受器","器件类型[仿生硬件]: 易失性忆阻器替代传统传感硬件"]},{"i":66093,"as":"烯烃复分解是构建碳–碳键的强力反应，但大多数钌催化剂在水介质中不稳定，制约其生物体系应用。本研究报道了带有生物偶联功能手柄的Ru(CAAC-5)烯烃复分解催化剂。通过烯胺烷基化制备带保护苯胺连接基的功能化CAAC-5配体，并与钌配位得到相应配合物。该杂化催化剂可催化关环复分解（RCM）反应，在水介质中寿命显著延长；在生物相关条件的基准RCM反应中表现出增强的催化稳健性，转换数最高达600。脱保护后可实现生物偶联应用。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["催化剂[Ru(CAAC-5)烯烃复分解]: 含生物偶联功能把手，在水介质中寿命延长"]},{"i":66094,"as":"铁死亡是临床重要的调节性细胞死亡形式，与多种退行性病理相关，发现新型铁死亡抑制剂具有重要转化价值。自由基捕获抗氧化剂（RTAs）能有效阻止脂质过氧化，是最重要的一类铁死亡抑制剂，但现有化合物发现与机制研究几乎完全依赖酚类或芳胺骨架，通常需高通量筛选或改编经典抗氧化剂。本研究证明Blatter自由基可有效抑制自氧化并抑制铁死亡；除本征强自由基捕获能力外，这些化合物还展现出独特性质，为铁死亡抑制剂开发提供了新骨架。","scd":{"b":6.5,"i":3.0,"r":5.5,"d":5.0,"t":5.0},"kp":["[自由基捕获抗氧化剂]: Blatter自由基可有效抑制脂质过氧化并抑制铁死亡"]},{"i":66095,"as":"具有高效二阶非线性光学响应的有机-无机手性杂化金属卤化物（HMHs）在光子学领域前景广阔，但兼具强二次谐波生成（SHG）和显著非线性手性光学响应的手性HMHs仍然稀缺。本研究报道了一对手性溴化铜(I)微米片(R-/S-MPZ)Cu2Br4（MPZ=2-甲基哌嗪鎓），结晶于非中心对称空间群P212121，由三配位三角平面CuBr3单元构成独特的一维之字链。得益于高度扭曲的Cu─Br骨架，其870 nm处SHG强度约为Y切石英的376倍，并伴有显著的非线性手性光学响应。","scd":{"b":5.5,"i":2.5,"r":5.0,"d":6.5,"t":5.0},"kp":["材料[手性杂化溴化铜(I)微米片 (R-/S-MPZ)Cu2Br4]: 非中心对称空间群，具有强二阶谐波生成与显著非线性手性光响应"]},{"i":66096,"as":"杂化金属卤化物展现多样的激发态行为，但压力诱导发射增强（PIEE）的分子层面起源尚不明确。本研究提出合理的分子设计策略，在零维碘化铜杂化物中分离出压力诱导的单分子变形作为PIEE的关键因素。通过系统调节季鏻阳离子烷基链长度，构建了(EtPPh3)2Cu2I4、(PrPPh3)2Cu2I4和(BuPPh3)2Cu2I4系列单晶，它们保持[Cu2I4]发光核心，但呈现不同的堆积模式与变形，压力下单分子几何演化导致发光强度最高增强208倍。","scd":{"b":6.0,"i":2.5,"r":5.5,"d":7.0,"t":5.0},"kp":["光致发光增强[压力诱导、零维碘化铜杂化物]: 强度增强208倍","机制[0D铜碘杂化物]: 单分子形变为压力诱导发光增强的关键因素"]},{"i":66097,"as":"有机太阳能电池（OSCs）在光电转换过程中存在较大的非辐射能量损失（ΔE3），限制性能提升。加入第三组分可有效优化活性层形貌并抑制非辐射复合，但组分选择缺乏精确理论指导。本研究提出静电势（ESP）位点效应新概念：在不改变分子平均ESP、能级或吸收的情况下，通过精确调节末端取代基位置调控局域ESP分布。基于该概念合理设计了两个不对称受体ZY-SCF3-N2F和ZY-SCF3-B2F并掺入体系，实现了低能量损失的高性能有机太阳能电池。","scd":{"b":5.5,"i":4.0,"r":5.0,"d":6.5,"t":5.0},"kp":["[有机太阳能电池第三组分]: 静电势位点效应可降低非辐射能量损失ΔE3、抑制非辐射复合"]},{"i":66098,"as":"纳米材料表面功能化化学仍是黑箱，动态修饰过程通常不可感知，严重制约先进纳米杂化材料的理性设计。本研究提出一种整体策略，通过近红外（NIR）介导的光诱导电子/能量转移-可逆加成-断裂链转移（PET-RAFT）聚合，将上转换纳米棒（UCNR）表面功能化从经验性结果转变为光学自报告过程。该三合一设计中，UCNR同时充当NIR捕获天线、聚合基底和光学信号单元，实现对聚合物壳层厚度可调的生长及时间精度可控的原位监测。","scd":{"b":6.5,"i":3.0,"r":5.5,"d":5.5,"t":5.0},"kp":["[上转换纳米棒表面功能化]: 借助NIR介导的光致电子/能量转移-可逆加成-断裂链转移实现光学自报告过程"]},{"i":66099,"as":"针对钠离子电池Sidorenkite型碳磷酸盐正极Na₃₋ₓFe(PO₄)(CO₃)实际容量仅为理论两电子反应一半的问题，研究阐明了其机理根源。结果表明，碳酸根稳定性和Na⁺迁移率并非性能限制瓶颈，真正原因在于刚性聚阴离子框架会破坏d⁴构型过渡金属中心（如Fe⁴⁺）的稳定性，在高荷电状态下产生晶格应变并抑制电子电导，导致仅能脱出一个Na当量。该发现通过同构体系验证，为设计高容量碳磷酸盐正极提供了机理依据。","scd":{"b":6.0,"i":4.5,"r":5.5,"d":7.5,"t":5.0},"kp":["正极[Sidorenkite型Na3-xFe(PO4)(CO3)钠离子电池]: 预测双电子高容量但实验仅实现一个钠当量，碳酸根位点为容量限制机理根源"]},{"i":66100,"as":"本综述系统评估了2021至2026年间生物基凝胶聚合物电解质（GPE）在可充电锌-空气电池（ZAB）中的表征策略。生物基GPE兼具电化学功能、机械适应性和可持续性，是ZAB的重要方向，但进展受限于缺乏严格且与应用相关的表征流程。文章将表征方法归为六类：机械与流变学表征、电化学分析与电池级测试、光谱技术、显微镜与纳米成像、热分析以及整体物理化学表征，并指出挑战、最佳实践和指导未来研究的高效工作流程。","scd":{"b":4.5,"i":4.0,"r":5.5,"d":5.0,"t":4.0},"kp":["电解质[可充电锌-空气电池]: 生物基凝胶聚合物电解质兼具电化学功能、机械适应性与可持续性"]},{"i":66101,"as":"针对钙钛矿太阳能电池在户外动态温度波动下的本征不稳定性，研究提出一系列双交联剂策略，以3-(三氯硅基)丙基甲基丙烯酸酯（MPTCl）修饰钙钛矿上界面。其中C=O基团与钙钛矿表面欠配位Pb²⁺强相互作用，稳定结构并减少界面电荷复合；甲基丙烯酸酯的C=C键发生原位聚合/交联，三氯硅基团则经水解与表面缩合形成交联网络。该多重功能协同策略同时提升了器件效率与耐温性能。","scd":{"b":5.5,"i":5.5,"r":5.0,"d":7.0,"t":5.0},"kp":["界面改性剂[钙钛矿太阳能电池上界面]: 3-(三氯硅基)丙基甲基丙烯酸酯(MPTCl)双交联，羰基C=O基团相互作用强，提升效率与温度耐受性"]},{"i":66102,"as":"硫化物基全固态锂金属电池（ASSLMB）采用锂金属负极可实现高能量密度，但锂金属/硫化物电解质界面处化学、电化学与机械退化耦合作用导致阻抗增长和电池失效。中间层策略可缓解界面退化、改善接触稳定性并调控电极-电解质界面的离子/电子传输，是稳定硫化物基全固态电池的有力途径。然而现有中间层机制多基于现象观察和经验性性能改进来解释，缺乏基于本征材料性质的深入理解，本文对此进行了系统性梳理。","scd":{"b":5.0,"i":5.0,"r":5.5,"d":6.0,"t":5.0},"kp":["[硫化物基全固态锂电池锂金属界面]: 中间层策略可缓解化学/电化学/机械耦合降解与阻抗增长"]},{"i":66103,"as":"","scd":null,"kp":[]},{"i":66104,"as":"研究报道了两种卤代硝基苯类挥发性固体添加剂（VSAs）——3,5-二氯硝基苯（DCNB）和3,5-二溴硝基苯（DBNB），可对有机太阳能电池的给体和受体相实现双向调控。传统VSA通常仅调节给体或受体相，难以协同优化微观结构。得益于各向异性静电势和大偶极矩，这两种添加剂同时促进给体D18的有序结晶和受体L8-BO的增强堆积，改善分子有序度并优化相分离，形成良好的互穿网络。基于D18:L8-BO的器件分别实现20.16%和19.80%的功率转换效率，而对照器件仅为17.87%，且器件兼具良好稳定性。","scd":{"b":7.0,"i":5.0,"r":5.0,"d":7.0,"t":6.0},"kp":["光电转换效率[协同挥发性固体添加剂有机太阳能电池]: 20.16%","挥发性固体添加剂[双向调控]: 3,5-二氯硝基苯(DCNB)与3,5-二溴硝基苯(DBNB)卤化硝基苯类添加剂","添加剂机理[各向异性静电势/大偶极矩]: 同时促进给体D18有序结晶并增强受体堆积"]},{"i":66105,"as":"研究探讨有机间隔阳离子调控低维钙钛矿结构进而影响热载流子弛豫的机制。通过瞬态吸收光谱与分子动力学模拟，揭示了间隔阳离子诱导的八面体畸变与晶格刚性决定极化子屏蔽与声子驱动弛豫之间的平衡。结果表明，苯乙铵间隔阳离子诱导显著畸变和较强的激子-声子耦合，促进极化子形成并延缓载流子冷却；刚性联二噻吩乙基铵间隔阳离子抑制畸变、稳定相干声子，加速热化过程；噻吩乙基铵则表现为中间行为。该结构-声子-载流子相互作用机制为设计热载流子冷却动力学提供了策略。","scd":{"b":6.5,"i":3.0,"r":5.0,"d":6.5,"t":6.0},"kp":["热载流子冷却调控[低维钙钛矿]: 有机间隔阳离子调控八面体畸变与晶格刚性，决定极化子屏蔽与声子弛豫的平衡","间隔阳离子[苯乙基铵]: 诱导显著八面体畸变与更强激子-声子耦合，有利于极化子形成","研究方法[低维钙钛矿]: 瞬态吸收光谱与分子动力学模拟结合"]},{"i":66106,"as":"该工作报道了一种用于碱性电解水的双功能电催化剂：在泡沫镍上通过顺序电沉积、可控硒化和置换反应，构建导电Co₂P纳米线骨架与Mo调控的NiSeO₄/NiSe₂异相壳层复合结构，并在O/Se配位空位处稳定原子级分散的Pt物种(Pt,Mo-NiSeO₄/NiSe₂@Co₂P)。得益于协同电子调控和异质界面工程，析氢反应在10和100 mA cm⁻²下仅需24和98 mV过电位，析氧反应仅需242和330 mV，兼具高活性、长耐久性与器件实用性。","scd":{"b":7.5,"i":6.5,"r":5.5,"d":7.5,"t":6.0},"kp":["催化剂[工业级碱性电解水]: Pt,Mo-NiSeO₄/NiSe₂@Co₂P异质结构","结构特征[催化剂]: 导电Co₂P纳米线骨架集成Mo调控的NiSeO₄/NiSe₂异相壳层","Pt位点稳定方式[原子级分散]: 稳定于O/Se配位空位位点","制备方法[催化剂]: 泡沫镍上顺序电沉积生长","催化性能[碱性电解水]: 双功能、高活性、长耐久性"]},{"i":66107,"as":"咔唑类自组装单分子层(SAM)因优异电学性能广泛应用于反式钙钛矿太阳能电池，但其固有刚性会对钙钛矿层造成严重机械应力。该工作在埋底接触处构建了不连续金属氧化物岛屿界面结构，以规避电-机械权衡：不连续形貌作为局域应变弛豫区，赋予界面宏观结构柔性，实现应变弛豫、缺陷密度降低的钙钛矿薄膜；同时修饰界面保持畅通的空穴选择性通道和最佳能级排列，由此获得的电池展现出优异性能。","scd":{"b":7.0,"i":5.0,"r":5.0,"d":6.5,"t":6.0},"kp":["埋底界面结构[反式钙钛矿太阳能电池]: 不连续金属氧化物岛状拓扑","界面材料[反式PSC]: 咔唑基自组装单分子层(SAMs)","设计目的[埋底接触]: 突破电学-力学权衡，赋予宏观结构柔性以缓解SAM刚性对钙钛矿层的机械应力"]},{"i":66108,"as":"该工作提出一种钙钛矿/硅叠层太阳能电池的全可扩展沉积策略，涵盖完整顶电池工艺：浸涂自组装单分子层空穴传输层、混合两步喷墨打印宽带隙钙钛矿吸光层，以及浸涂界面钝化层。工艺展现出优异的可重复性和高器件性能。与绒面硅底电池集成后，叠层太阳能电池光电转换效率超过30%，为单片钙钛矿/硅叠层电池的商业化部署提供了与既有硅制造工艺兼容的可行制备路线。","scd":{"b":7.5,"i":7.0,"r":5.5,"d":7.5,"t":6.0},"kp":["光电转换效率[钙钛矿/硅叠层太阳能电池]: 30%","制备工艺[钙钛矿顶电池规模化沉积]: 两步喷墨打印与浸涂混合策略","空穴传输层[可规模化工艺]: 浸涂自组装单分子层(SAM)","工艺兼容性[产业化]: 薄膜均匀且与既有硅制造工艺兼容"]},{"i":66109,"as":"水系铝离子电池因铝资源丰富、成本低、理论容量高而受关注，但受限于电解液稳定性差、铝负极严重腐蚀与钝化以及Al³⁺扩散动力学缓慢。该工作提出电解液-负极耦合策略：将水合共晶电解液与电沉积Al-Zn合金负极结合。优化电解液AETH30由Al(ClO₄)₃·9H₂O、乙二醇、磷酸三乙酯和水按1:6:4:30摩尔比组成，乙二醇与磷酸三乙酯重组氢键网络并构建动态混合Al³⁺溶剂化环境，降低水主导的副反应，实现-30至50°C宽温区稳定运行。","scd":{"b":7.0,"i":5.0,"r":5.5,"d":7.0,"t":6.0},"kp":["工作温区[水系铝离子电池]: -30至50°C","电解液-负极耦合策略[宽温区AAIB]: 水合共晶电解液结合电沉积Al-Zn合金负极","电池负极[水系铝离子电池]: 电沉积Al-Zn合金","技术优势[水系铝离子电池]: 铝储量丰富、成本低、理论容量高"]},{"i":66110,"as":"该工作引入一个完全基于实验室的多模态原位分析平台，在同一个密封锂硫电池内同步集成EIS/DRT、拉曼光谱、紫外-可见反射光谱、温度监测和恒电流循环测试，并在长达20个循环的观测窗口内运行演示。通过在同一电池上结合多种技术，实现对不同电解液体系中多硫化物物种演化、传输限制和阻抗演变的交叉关联对比分析，为研究电解液组成对电池各过程的影响及电池退化机制提供了有力工具。","scd":{"b":5.5,"i":4.0,"r":5.0,"d":6.5,"t":6.0},"kp":["分析方法[锂硫电池]: 全实验室多模态operando原位平台","同步联用技术[同一电池]: EIS/DRT、拉曼光谱、UV-vis等","研究目标[锂硫电池]: 隔离并解析电解液组成对电池各退化过程的影响机制"]},{"i":66111,"as":"酸性电催化CO₂还原虽可最大化碳效率，但易受析氢竞争反应影响，且高电流密度下局部pH骤增会扩散至本体电解液，使名义酸性条件趋向中性/碱性。该工作将具有高质子亲和力的Ce物种引入多孔Cu纳米片表面，构建缓解质子的Cu─O─Ce活性位点。除局部*CO积累驱动的C─C耦合外，Cu─O─Ce基元加速*CO形成及其质子化，实现朝向并超越*CO─*CHO二聚的下坡质子耦合电子转移(PCET)，从而在酸性条件下实现稳定的CO₂电催化转化。","scd":{"b":7.0,"i":5.0,"r":5.0,"d":6.5,"t":6.0},"kp":["催化剂改性[酸性CO₂电催化]: 将高质子亲和性的Ce物种掺入多孔电极表面","技术目标[酸性CO₂还原]: 高电流密度下抑制析氢并稳定局部/体相pH，维持酸性反应环境","运行挑战[酸性CO₂RR]: 高电流密度引发局部pH骤升并扩散至体相电解液，使酸性还原退化为中性/碱性条件"]},{"i":66112,"as":"该工作提出一种混合碱/酸甲醛制氢燃料电池(h-A/AFHFC)，将碱性甲醛氧化与酸性氧还原耦合。采用柱状分支AgCu催化剂，电池实现2.0 V输出电压和482 mW cm⁻²峰值功率密度，并稳定运行超过110小时。除发电外，该器件利用甲醛极低的氧化电位及其单电子脱氢路径，在无*CO、无CO₂的电化学过程中联产氢气和甲酸盐，重新定义了燃料电池的角色，同时克服了传统电合成高能耗和催化剂降解的局限。","scd":{"b":8.0,"i":5.0,"r":6.0,"d":7.5,"t":6.0},"kp":["输出电压[混合碱/酸甲醛制氢燃料电池h-A/AFHFC]: 2.0 V","峰值功率密度[h-A/AFHFC]: 482 mW/cm²","阳极催化剂[甲醛氧化]: 柱状分支AgCu催化剂","工作机理[无CO₂甲醛燃料电池]: 碱性甲醛氧化与酸性氧还原耦合"]},{"i":66113,"as":"液晶弹性体（LCE）兼具液晶各向异性与橡胶弹性，是软体驱动器的核心材料。随着领域从实验室演示走向软体机器人和生物医学器件的实际应用，正从简单均匀变形向空间可编程性质与集成功能演进。其设计原则核心是异质集成，即在统一LCE体系内对化学、结构或取向差异进行有意的空间设计，从而实现均质LCE无法达到的差异化驱动方向、力学梯度和顺序响应性的精确编程。文章总结了相关设计原理与功能实现路径。","scd":{"b":4.0,"i":4.0,"r":4.0,"d":4.0,"t":4.0},"kp":["设计原则[空间可编程液晶弹性体]: 异质集成实现空间可编程特性与集成功能","材料本质[液晶弹性体]: 液晶各向异性与橡胶弹性的融合","应用方向[先进LCE]: 软体机器人与生物医学器件的软驱动器"]},{"i":66114,"as":"硫化物基全固态锂电池受限于富镍层状氧化物正极的界面不稳定性和迟缓的锂离子动力学。该工作提出以正极异质界面处电子态连续性为核心的设计原则：对单晶LiNi₀.₉₄Co₀.₀₄Mn₀.₀₂O₂共掺杂选定的第五周期元素(Y、Zr、Nb、Mo)，自组装形成功能空间分化的异质界面。热力学驱动偏析生成LiNbO₃/Li₂MoO₄外层钝化层以抑制副反应，并与富Y/Zr的亚表面岩盐相中间层保持共格，后者锚定晶格氧，从而同步解决界面不稳定与离子动力学问题，实现稳定的全固态锂电池。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.5,"t":5.0},"kp":["正极材料[单晶富镍]: LiNi0.94Co0.04Mn0.02O2","共掺杂元素[第5周期]: Y、Zr、Nb、Mo","设计策略[正极异质界面]: 电子态连续性"]},{"i":66115,"as":"过渡金属二硫属化物（TMD）的吸附驱动反应活性高度依赖位点，主要集中在边缘，而惰性基底面占据绝大部分暴露面积。研究提出一种强脉冲光驱动闪热合成方法，在环境空气中于10毫秒脉冲内直接将四硫代钼酸铵转化为富含边缘的少层MoS₂纳米片（FTS-MoS₂）。超快光热冲击（1192–1811°C，升/降温速率约10⁵/10⁴°C s⁻¹）抑制了面内粗化和金属团聚，实现单原子修饰与双位点设计，获得高性能室温化学电阻传感器。","scd":{"b":6.5,"i":3.0,"r":5.0,"d":7.0,"t":5.0},"kp":["合成方法: 强脉冲光驱动闪热合成","结构设计[传感器/TMD]: 双位点设计（富集边缘+激活基面）","应用场景: 室温化学电阻传感器"]},{"i":66116,"as":"面向生物医学、机器人和传感应用的可穿戴集成电子器件需在保持可穿戴性的同时提高紧凑性与功能复杂度，但电子与微流控组件的异质制造、材料失配和复杂组装阻碍了无缝集成。研究提出选择性激光烧结与石墨化（SLSG）3D打印技术，通过对富碳前驱体（如聚醚醚酮PEEK粉末）的自适应光子调制，在同一基体上无缝一体化制造3D立体电路与3D流体通道，同步形成绝缘烧结结构与导电石墨化结构，实现单体式可穿戴器件制造。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["制造技术: 选择性激光烧结与石墨化(SLSG) 3D打印","集成特性[可穿戴器件]: 主体电路与立体微流体单基体一体化无缝集成"]},{"i":66117,"as":"针对现有NO探针多会干扰NO生理活性、难以无损监测的问题，研究提出分子间氢键诱导顺磁性（HIP）新策略，实现体内基于化学交换饱和转移（CEST）成像的外源NO无损检测。Arg-Cu(II)自组装形成羧酸铜配合物，通过分子间氢键传播磁偶极-偶极相互作用，将精氨酸的CEST信号移至34.0 ppm；当精氨酸代谢释放NO后，Arg-Cu(II)单元间氢键解离，CEST信号相应改变，从而实现NO生成的无创、可视化监测。","scd":{"b":6.5,"i":2.5,"r":5.0,"d":6.5,"t":5.0},"kp":["检测策略[NO检测]: 分子间氢键诱导顺磁性(HIP)","成像技术[NO活体监测]: CEST化学交换饱和转移成像","探针组成: Arg–Cu(II)组装","检测特性: 无损、不干扰NO生理活性"]},{"i":66118,"as":"新兴光电系统要求光电探测器提供应用定义的传递特性，而非单纯高响应度或快响应。研究提出一种以频率为核心的响应调制策略：将基于时间积分电荷的交流-直流（AC-DC）映射与跨异质结区内建电场的连续调控相结合，该异质结具有拮抗光响应，使传递函数在频域可定制。以卤化铅钙钛矿为模型材料，实现了频率响应可定制的钙钛矿光电探测器，避免了波长/强度域调控带来的源端复杂性和功耗增加。","scd":{"b":6.5,"i":3.0,"r":5.5,"d":6.5,"t":5.0},"kp":["响应调控策略[光电探测器]: 以频率为核心的调制策略","性能特征: 可定制频率响应"]},{"i":66119,"as":"Sn-Pb混合钙钛矿器件在光伏和红外光电探测领域潜力巨大，但钙钛矿体相及与空穴传输层（HTL）界面的非辐射复合限制其性能。在无HTL结构中，埋底钙钛矿/ITO界面成为载流子提取与复合的主要瓶颈。研究将异烟肼（INH）引入FA₀.₆MA₀.₃Cs₀.₁Pb₀.₅Sn₀.₅I₃钙钛矿薄膜中，原位形成偶极界面并建立内建电场，抑制界面非辐射复合，实现无空穴传输层的高效Sn-Pb混合钙钛矿太阳能电池与光电探测器。","scd":{"b":6.5,"i":4.0,"r":5.5,"d":7.0,"t":5.0},"kp":["电池结构[Sn–Pb钙钛矿]: 无空穴传输层(HTL-free)","关键工程手段: 原位偶极工程","瓶颈界面[HTL-free结构]: 埋底钙钛矿/ITO界面"]},{"i":66120,"as":"针对传统垂直金属/阻变层/金属(V-MRM)忆阻器电场过强、感知响应有限、功能模式刚性、存在变异性和过冲等问题，研究提出一种两端准垂直(QV)范德华异质结构忆阻器作为光可重构AI硬件。与V-MRM器件强而刚性的垂直电场不同，QV-vdWH忆阻器实现了显著软化且可调的电场分布，从而改善感知响应能力并提供灵活可重构的功能模式，为感算一体的人工智能硬件提供了新的器件架构。","scd":{"b":7.0,"i":3.5,"r":5.5,"d":6.5,"t":5.0},"kp":["器件结构: 单个准垂直范德华异质结构忆阻器","功能特性: 光可重构人工智能硬件"]},{"i":66121,"as":"水系锌金属电池在大规模储能中前景广阔，但锌可逆性差制约其实际应用。研究提出远程电外延(REE)策略，以单层石墨烯包覆的Cu(111)衬底作为外延集流体，通过衬底-电位传递实现完美的晶体学遗传，并借助界面应变弛豫容纳晶格失配，理论与仪器表征均证实了这一机制，最终获得全维度晶体学连贯的高质量单晶锌负极，可提升锌负极电化学性能与循环可逆性。","scd":{"b":7.0,"i":5.0,"r":5.5,"d":7.0,"t":5.0},"kp":["负极材料: 全维度晶体学连贯单晶锌负极","制备策略[单晶Zn电极]: 远程电外延(REE)","衬底结构: 单层石墨烯包覆Cu(111)"]},{"i":66122,"as":"富锂锰基氧化物(LRMO)依靠晶格氧氧化还原获得高容量，但高电压下氧释放会氧化固态电解质，导致界面电阻快速增加；纳米化虽改善固态动力学，却暴露更多欠配位表面氧加剧界面退化。密度泛函理论筛选表明磷酸盐是稳定表面氧最有效的含氧阴离子基团。据此研究通过LRMO与LiPO₂F₂一步机械化学反应构建Li-P-F-O键合拓扑，同时细化颗粒、引入近表面氟，并形成含P-O、P-F、Li-F键合环境的保形非晶界面相，从而稳定氧氧化还原并提升界面稳定性，适用于高倍率LRMO基全固态锂电池。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.5,"t":5.0},"kp":["正极材料[全固态锂电池]: 富锂锰基氧化物(LRMO)","DFT筛选结论[稳定表面氧]: 磷酸根为最有效含氧阴离子基元","关键机制: Li─P─F─O键合拓扑决定氧氧化还原与界面稳定性"]},{"i":66123,"as":"本文综述了意大利ENEA Frascati园区正在建设的偏滤器托卡马克试验装置(DTT)的加热与电流驱动(HCD)系统的设计要点与挑战，该装置旨在灵活且易于改造的环境中开展功率排出研究。DTT选择技术最成熟、对未来反应堆具有参考价值的HCD系统：第一阶段所需电子回旋共振加热和离子回旋共振加热系统，其设计与采购已相当成熟；第三套系统为基于负离子加速的中性束注入器，将在第一阶段之后于第二阶段安装。","scd":{"b":6.0,"i":6.0,"r":5.0,"d":6.5,"t":5.0},"kp":["设施[DTT装置/ENEA Frascati]: 偏滤器托卡马克试验装置，在建","系统组成[HCD]: 选用技术最成熟、对未来反应堆具有相关性的加热与电流驱动系统","研究目标: 灵活可改的功率排出研究"]},{"i":66124,"as":"托卡马克等离子体大破裂严重威胁装置安全稳定运行，高能逃逸电子形成的逃逸电流是主要危害之一。在J-TEXT托卡马克上，研究团队利用低Z氘/氖混合物的碎裂弹丸注入(SPI)和大量气体注入(MGI)开展了逃逸电流缓解实验。结果表明，SPI和MGI注入大量低Z混合杂质均可延长逃逸电流平台持续时间，并降低混合杂质注入后的逃逸电子能量，为破裂缓解策略提供了实验依据。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["高Z杂质[破裂缓解]: 有效耗散runaway电流","低-Z氘[runaway电流]: 可实现良性终止"]},{"i":66125,"as":"联合国承诺到2030年遏止并扭转生物多样性丧失，但采矿仍是生物多样性下降的重要驱动因素。研究量化了当前145,000平方公里采矿用地对生物多样性的威胁，发现其中34%（49,000平方公里）与保护优先区域(CPZs)重叠，涉及超过2,300个物种的分布区，其中许多已被列为受威胁物种。这些威胁跨越14个生物群系，在脆弱生态系统中相对影响尤为突出，凸显了全球保护战略中量化评估采矿威胁的紧迫性。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["当前采矿业威胁面积[保护优先区域]: 145,000 km²"]},{"i":66126,"as":"出版商更正声明，涉及BRCA1-A复合物泛素链供给机制相关研究的更正。","scd":null,"kp":[]},{"i":66127,"as":"作者更正声明，涉及单细胞图谱解析滑翔哺乳动物飞膜发育机制研究的更正。","scd":null,"kp":[]},{"i":66128,"as":"作者更正声明，涉及神经元-星形胶质细胞组合体tau病模型单细胞转录组图谱研究的更正。","scd":null,"kp":[]},{"i":66129,"as":"作者更正声明，涉及口蹄疫病毒抗原景观及免疫原性降低机制的原子分辨率结构解析研究的更正。","scd":null,"kp":[]},{"i":66130,"as":"作者更正声明，涉及维生素B12通过卵黄蛋白原储备诱导捕食记忆机制研究的更正。","scd":null,"kp":[]},{"i":66131,"as":"样品制备是冷冻电镜结构分析的关键限速步骤，主要难点在于气液界面对蛋白质分子的损伤。研究引入碳纳米管(CNTs)作为一维纤维状支撑膜，CNTs与大分子相互作用，有效保护其免受气液界面影响，大分子以多种取向围绕CNTs排列。经亲和标签生物功能化的CNTs可特异性结合目标大分子，实现从细胞裂解液中直接纯化靶标并在载网上组装复合物用于冷冻电镜分析。此外CNTs载网兼容细胞培养，可无缝整合进冷冻电镜工作流程。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["碳纳米管[冷冻电镜样品制备]: 一维纤维支撑材料，保护大分子免受空气-水界面影响","碳纳米管[生物功能化]: 可偶联亲和标签"]},{"i":66132,"as":"蛋白酶体核心颗粒(CP)可被Blm10/PA200封端，促进非折叠蛋白的ATP非依赖性降解，其上调还会削弱抗原多样性并影响免疫治疗。Blm10-CP蛋白酶体的组装过程此前未知。研究通过冷冻电镜解析了五种CP中间体复合物结构，其中两种包含Blm10。结果显示Blm10与Pba1/Pba2伴侣复合物与CP中间体的结合互斥，二者均可导向成熟CP的产生，且Pba1/Pba2与Blm10在CP组装中无协同作用，表明蛋白酶体核心颗粒存在平行的组装途径。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["Blm10/PA200[蛋白酶体核心颗粒封盖]: 促进不依赖ATP的无序蛋白降解","中间体复合物[冷冻电镜解析]: 五种CP组装中间体结构"]},{"i":66133,"as":"作者更正声明，涉及CANTAC-seq分析揭示E2f1与Otx1协同调控爪蟾合子基因组激活研究的更正。","scd":null,"kp":[]},{"i":66134,"as":"基因表达在看似同质的细胞群体内部也存在显著变异，但细胞间表达变异的遗传调控机制尚不清楚。研究提出MEOTIVE统计框架，在建模均值-方差依赖关系的同时鉴定影响基因表达变异的遗传效应位点(sc-veQTLs)。应用于OneK1K队列980名供体约120万个外周血单个核细胞的单细胞RNA测序数据，研究在多种血液细胞类型中鉴定出14至3,488个具有显著sc-veQTLs的基因，其中2,103个为共享位点，揭示了细胞类型特异性的个体内基因表达变异相关遗传变异及其基因组调控机制。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["技术框架[细胞内基因表达变异]: MEISTIVE统计框架，识别基因表达变异性的遗传效应","研究对象[个体内表达变异]: 细胞间表达变异性的遗传调控机制"]},{"i":66135,"as":"卵母细胞质量的年龄相关下降是女性不孕的主要风险因素，但衰老卵母细胞的蛋白质组图谱此前基本空白。研究对小鼠和人类的GV/MII期衰老卵母细胞进行单细胞蛋白质组与转录组联合分析，揭示了卵母细胞衰老过程中物种特异性和阶段特异性的蛋白组与转录组变化。研究发现蛋白质组与转录组改变存在解耦现象，表明衰老卵母细胞的蛋白质变化并非主要由RNA水平驱动；同时捕获了衰老卵母细胞的分子异质性，鉴定出MCT4为卵母细胞衰老候选标志物，功能研究提示失调的乳酸代谢在卵母细胞衰老中发挥作用。","scd":{"b":7.5,"i":3.0,"r":6.5,"d":8.0,"t":6.0},"kp":["技术方法[单卵母细胞]: 蛋白质组-转录组联合图谱","研究对象[卵母细胞衰老]: 失调的乳酸代谢","样本条件[GV/MII卵母细胞]: 小鼠与人类单细胞蛋白组/转录组联合分析"]},{"i":66136,"as":"人诺如病毒是全球急性胃肠炎的主要病原，目前尚无获批疫苗或抗病毒疗法。非结构蛋白NS3是超家族3(SF3)的膜结合AAA+ ATPase，在病毒复制周期中具有多种推测功能，但其结构未知。研究构建了可溶、六聚且具有催化活性的NS3形式，并在核苷酸类似物存在下以2.9埃分辨率解析其冷冻电镜结构。该结构呈现AAA+马达典型的分裂锁垫构型，提示其通过hand-over-hand易位机制运行，结合生化与单分子实验提示NS3在RNA转运中的作用，为理解病毒基因组复制和膜重塑机制提供基础。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.5,"t":6.0},"kp":["NS3蛋白属性[诺如病毒]: 膜结合AAA+ ATPase（SF3超家族）","工程化蛋白[NS3结构研究]: 可溶性、六聚体、具催化活性"]},{"i":66137,"as":"噬菌体已进化出多种抗CRISPR蛋白(Acr)或RNA型抗CRISPR(Racr)直接干扰宿主免疫，但其他对抗机制尚待探索。研究报道了一种噬菌体编码的双蛋白系统Healer，通过切割后DNA修复机制中和CRISPR免疫。该系统包含含DUF669结构域的Gp63和含AAA结构域的Gp64。机制研究表明Gp63是CRISPR诱导DNA断裂的快速响应效应蛋白，其结合单链DNA后促进Gp64介导的同源重组，修复CRISPR造成的噬菌体DNA断裂并维持噬菌体存活；共表达两蛋白可有效支持噬菌体复制。","scd":{"b":8.5,"i":2.5,"r":7.5,"d":7.0,"t":6.0},"kp":["反CRISPR机制[噬菌体Healer系统]: 切割后DNA修复机制","系统组成[Healer]: Gp63（含DUF669结构域）和Gp64（含AAA结构域）双蛋白系统"]},{"i":66138,"as":"作者更正声明，涉及溶酶体TRAP清除病毒及变异体的新型免疫机制研究的更正。","scd":{"b":1.0,"i":1.0,"r":1.0,"d":1.0,"t":3.0},"kp":[]},{"i":66139,"as":"单纯疱疹病毒1型(HSV-1)是散发性病毒性脑炎的主要病因，失控的病毒复制与神经炎症导致致命性脑损伤。人类遗传性RIPK3缺陷易导致重症，但其保护机制不明。研究结合单细胞转录组学、基因敲除模型及对病毒复制、干扰素产生和细胞死亡的分析，显示RIPK3是细胞类型特异性的分子开关：其支架功能在多种中枢神经系统细胞中促进干扰素应答和病毒控制，并通过RIPK3依赖性凋亡限制髓系细胞积累；而星形胶质细胞中RIPK3激酶活性则触发坏死性凋亡，导致神经病变，揭示其在保护与致病间的双重角色。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.5,"t":6.0},"kp":["RIPK3功能[HSV-1脑炎]: 神经保护与神经病变之间的分子开关","RIPK3缺陷关联[人类遗传]: 易感严重单纯疱疹病毒脑炎"]},{"i":66140,"as":"人类饮食与生活方式跨文化差异巨大，塑造了全球肠道微生物组的多样性与功能，但方法学异质性限制了可比的跨人群研究。人类饮食与微生物组计划(THDMI)对美国、英国、西班牙、墨西哥和日本1,976名参与者进行标准化招募、膳食评估和宏基因组鸟枪测序，以区分生物与技术差异。研究观察到营养摄入、食物消费和微生物组成的显著地理差异，以及与饮食相关的共享和国家特异特征；稀疏典型相关与机器学习分析显示微生物组-饮食关联很大程度上具有人群特异性。","scd":{"b":6.0,"i":4.0,"r":7.0,"d":8.5,"t":6.0},"kp":["样本规模[THDMI计划]: 五国1,976名参与者","技术方法[肠道微生物组]: 标准化招募+膳食评估+鸟枪法宏基因组测序","覆盖国家[跨人群研究]: 美国、英国、西班牙、墨西哥、日本"]},{"i":66141,"as":"Dlk1-Dio3位点的非编码RNA对出生后早期代谢组织成熟至关重要，但其在成熟器官中的作用不明。研究显示miR-379/miR-410簇微小RNA在肥胖人群肝脏及多种代谢功能障碍小鼠模型中显著上调。在成年期通过肝细胞特异性表达诱骗序列组合抑制该miRNA簇，可降低甘油三酯、总胆固醇和LDL胆固醇循环水平，降低基础血糖，并改善葡萄糖耐量和胰岛素敏感性，且不受性别影响。与诱骗触发的PI3K/mTOR信号增强一致，表达组合诱骗的肝细胞表现出增强的代谢功能，使雄性糖尿病和肥胖模型中的糖脂稳态恢复正常。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.5,"t":6.0},"kp":["干预策略[miR-379/miR-410簇]: 肝细胞特异性表达诱饵序列的组合抑制","干预时机[成年 onset]: 成年后组合抑制miRNA簇","效应[糖尿病肥胖模型]: 恢复糖脂稳态、降低甘油三酯","表达变化[肥胖肝脏]: miR-379/miR-410簇显著上调"]},{"i":66142,"as":"虫媒正义单链RNA病毒包含多种威胁人类健康的病原，理解病毒基因组的胞内动态及宿主因子互作对抗病毒策略至关重要。研究构建了双标记的寨卡病毒和基孔肯雅病毒，整合Mango-II适配体用于RNA富集和实时成像，实现了活细胞中黄病毒RNA的高分辨率成像。与病毒复制蛋白的串联成像揭示了复制复合物和RNA分子的胞内动态；鉴定出200余个高置信度病毒RNA宿主互作因子，并验证了已有数据集中的355个候选靶点。剪接体因子SFPQ被确定为两种病毒共有的互作因子，可降低病毒RNA产生。","scd":{"b":7.5,"i":3.5,"r":7.0,"d":7.5,"t":6.0},"kp":["病毒改造[寨卡/基孔肯雅病毒]: 双重标记，整合Mango-II适配体","技术能力[活体成像]: RNA pulldown与实时成像，实现黄病毒RNA活细胞高分辨率成像"]},{"i":66143,"as":"蛋白质水凝胶因良好的应力松弛行为而有望用作干细胞和类器官3D培养的人工细胞外基质，链间缠结基序是构建此类水凝胶的有力策略，但难以在保证缠结的同时调控结合能等性质。研究提出TangleDoc——一个用于从头设计同源二聚体缠结蛋白质的深度学习框架。TangleDiff可生成多样化可折叠的缠结序列，计算机模拟成功率超过70%，实现了缠结蛋白的可定制应力松弛特性，为构建具有可编程力学性能的蛋白质水凝胶提供了设计工具。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":7.0,"t":6.0},"kp":["材料策略[蛋白质水凝胶]: 链间缠结基序","设计方法[缠结基序设计]: 深度学习驱动，可定制应力松弛行为","应用方向[蛋白质水凝胶]: 3D干细胞与类器官培养的人工细胞外基质"]},{"i":66144,"as":"作者更正声明，涉及时空噪声散射实现超高速光学加密技术研究的更正。","scd":{"b":5.0,"i":1.0,"r":2.0,"d":2.0,"t":3.0},"kp":[]},{"i":66145,"as":"纯电动汽车(BEVs)通常被认为归因生命周期温室气体排放低于燃油车，但电动车里程与寿命的数据有限，使对比存在不确定性。研究利用英国所有电动汽车的数据评估其与常规车和混动车的里程和寿命差异及对归因生命周期排放的影响。结果显示第一代BEV行驶里程较少且寿命不及常规车辆，但生命周期排放仍更低；预计2026年购买的BEV年行驶里程和寿命将追平常规车辆，进一步降低其全生命周期排放。","scd":{"b":5.5,"i":6.0,"r":6.0,"d":8.0,"t":6.0},"kp":["排放结论[BEV对比燃油车]: 归因生命周期温室气体排放通常更低","数据基础[英国]: 基于全部英国电动汽车的行驶里程与寿命数据"]},{"i":66146,"as":"铁电通量闭合结构因具有可逆翻转和低功耗特性而成为高性能存储器的候选，但由于衬底对极性薄膜生长的约束，其集成到存储器件中一直难以实现。研究演示了基于含相同极性通量闭合的自支撑薄膜的铁电场效应晶体管(Fe-FETs)。自支撑薄膜中通量闭合的保持由极化的本征自组织驱动，以最小化弹性与静电联合能量。通量闭合结构表现出低矫顽电场、可忽略的漏电流以及高达10¹⁰次的耐久性。基于此构建的互补金属氧化物器件实现了非易失性场效应存储功能。","scd":{"b":7.5,"i":5.0,"r":6.0,"d":6.5,"t":6.0},"kp":["存储器件类型[铁电磁通闭合]: 基于独立薄膜的铁电场效应晶体管阵列","器件特性[铁电磁通闭合]: 可逆翻转、低功耗、非易失性场效应存储"]},{"i":66147,"as":"光频梳已深刻影响精密光谱学及原子、分子乃至核跃迁的探测能力。为扩展可研究的能量尺度与体系类型，研究者持续推进从太赫兹到真空紫外乃至更高频率的频率梳光源。双光梳光谱学借助这些光源的发展，可对复杂光谱进行宽带吸收测量，突破单光梳直接光谱的限制。然而迄今双光梳方法仍无法直接触及位于真空紫外波段的许多重要跃迁，本文介绍了真空紫外双光梳光谱学的进展，将该技术拓展至真空紫外频率区间。","scd":{"b":7.0,"i":4.0,"r":5.5,"d":6.0,"t":6.0},"kp":["光谱技术[真空紫外]: 双光梳光谱学","频率范围[双光梳光源]: 从太赫兹拓展至真空紫外频段"]},{"i":66148,"as":"作者更正声明，涉及工业制绒硅上冰山状金字塔结构钙钛矿-硅叠层太阳能电池研究的更正。","scd":{"b":6.5,"i":7.0,"r":4.0,"d":6.0,"t":5.0},"kp":["转换效率[工业制绒硅冰山状金字塔结构钙钛矿-硅叠层]: 33%"]},{"i":66149,"as":"本文研究了苯的同分异构体环己烯-3-炔（4）和1,2,3-环己三烯（5）的合成应用。与已被广泛应用的苯炔、环己炔和1,2-环己二烯不同，这类苯同分异构体此前较少受到关注。研究者将环己烯-3-炔和1,2,3-环己三烯成功引入多种串联反应，包括1,3-双胺化反应、亲核加成-ene反应以及亲核加成-[4+2]环加成反应，用于制备多取代1,3-环己二烯类化合物。此外还观察到一个1,5-磺酰基迁移过程，进一步拓展了此类高活性中间体在有机合成中的应用潜力。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":5.0,"t":6.0},"kp":["反应类型[环己-3-炔与1,2,3-环己三烯]: 串联反应","研究对象[中性六元活性物种]: 苯炔、环己炔、1,2-环己二烯及苯同分异构体(环己烯-3-炔、1,2,3-环己三烯、1,2,4-环己三烯)"]},{"i":66150,"as":"自动驾驶电动汽车的大规模商用需要自动化充电方案，感应充电面临铁氧体体系在效率、功率密度和热稳定性方面的挑战。本文报道了一种采用铁基纳米晶合金的感应充电系统，通过材料与系统层面的联合优化实现。与常规追求最大磁导率的思路不同，分析表明中等磁导率更契合系统需求。通过应力退火处理，材料实现了2330的有效磁导率和135 kW/m³的磁芯损耗（85 kHz、0.2 T条件下）。随后采用线圈对准层压技术将材料制成磁芯条，构建出高效感应充电系统，为铁氧体替代方案提供了材料与系统协同设计的思路。","scd":{"b":6.5,"i":7.0,"r":6.0,"d":7.0,"t":6.5},"kp":["磁芯材料[感应充电系统]: 经应力退火、具有高感生磁各向异性的铁基纳米晶合金","性能瓶颈[铁氧体感应充电]: 存在效率、功率密度和热稳定性挑战","设计思路[Fe基纳米晶]: 超越传统最大磁导率导向的材料与系统协同优化"]},{"i":66151,"as":"白光圆偏振发光（WCPL）材料需同时满足理想CIE坐标下的高显色指数（CRI）、覆盖全可见光区的大不对称因子（glum），但化学设计空间庞大且依赖直觉的人工实验筛选效率低下。本文提出一种AI辅助的交互式实验-学习进化策略来加速发现最优权衡的WCPL材料，该策略在每次迭代优化周期中集成模型推荐、实验验证与主动学习。系统采用多目标优化算法自动引导实验设计，并构建了双环结构框架，通过机器学习与闭环实验的反复迭代，有效压缩探索空间，实现覆盖全可见光区且兼具高CRI和大glum值的白光圆偏振发光材料的高效发现。","scd":{"b":7.0,"i":4.0,"r":6.5,"d":6.0,"t":6.5},"kp":["发光特性[白光圆偏振发光材料]: 覆盖整个可见光区的高glum值","设计方法[白光CPL材料]: 双环主动学习的AI辅助交互式实验-学习进化","优化目标[白光CPL]: 高显色指数(CRI)、理想CIE坐标与大glum值兼顾"]},{"i":66152,"as":"针对机器人对柔性物体微操控这一基础性难题，本文提出了一种力-流协同操控方案。该方案通过动态调节气液界面的流场，实现对漂浮微物体的精确操控，并同时控制操控与对焦平面，从而应对外力、材料固有属性与环境因素之间复杂耦合带来的形变控制挑战。研究者提出基于可逆神经网络的实时流场预测框架FlowNet，能够对输入流与产生的时空流场进行双向预测。该框架为流场的实时估计与逆向求解提供支持，实现了微尺度下柔性物体的灵巧操控与精确控制，为微操作机器人系统的学习方法提供了新途径。","scd":{"b":6.5,"i":4.0,"r":5.5,"d":5.5,"t":6.5},"kp":["操控方案[柔性微物体]: 力-流协同操控学习方法","实现方式[漂浮微物体]: 动态调节外力实现精确操控"]},{"i":66153,"as":"受动物在野外非结构化环境中多模态运动的启发，本文设计了一种面向胃肠道等多变环境的小型、紧凑、可折叠且坚固的软体电磁机器人。该机器人具有超过九种运动模式，采用六辐条弹性体身体，内嵌液态金属通道，在静态磁场下通过拉普拉斯力驱动。这一设计使机器人能够快速切换运动模式，适应包括黏弹性黏液、复杂皱褶和贲门等狭窄开口在内的人体消化道复杂结构。该工作为在受限和非结构化环境中执行任务的多模态导航软体机器人提供了紧凑而稳健的解决方案，在体内诊疗应用方面具有潜力。","scd":{"b":7.0,"i":4.5,"r":6.0,"d":6.5,"t":6.5},"kp":["运动模式数[可折叠小尺度软体电磁机器人]: 超过9种多模态运动","结构特征[软体电磁机器人]: 可折叠、六支撑结构","应用环境[胃肠道]: 受限非结构化环境多模态导航"]},{"i":66154,"as":"周围神经损伤修复的金标准是自体神经移植，但供体神经采集会造成二次手术创口、麻木，且20%的病例出现供体部位慢性神经病理性疼痛。本文开发了一种聚己内酯（PCL）多通道仿生支架，其表面特征可促进细胞和血管附着，并支持轴突快速、线性再生，可供轴突再生的横截面积超过自体移植物。在1 cm大鼠和3 cm兔子坐骨神经缺损模型中，与自体神经移植及FDA已批准的神经导管相比，该仿生支架在轴突再生、腓肠肌与脊髓运动神经元之间的功能重建以及诱发运动反应等指标上达到或优于自体移植效果。","scd":{"b":6.5,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["自体移植供体部位慢性神经病理性疼痛发生率: 20%","支架材料: 聚己内酯(PCL)多通道仿生支架","支架结构特征: 表面特征促进细胞与血管附着及快速线性轴突再生","可用于轴突再生的横截面积: 超过自体移植物"]},{"i":66155,"as":"硅晶体管的微缩正逼近物理极限，IRDS路线图预测沟道长度将在2037年停留在12 nm。二维半导体是延续晶体管微缩的候选材料，但尚无实验超越先进硅器件的基本开关极限。本文报道了物理沟道长度小于5 nm的单层MoS₂晶体管，实现88 mV/dec的亚阈值摆幅和超过10⁶的开关比，在同等尺寸下超越了硅的理论亚阈值极限及最先进的新兴半导体晶体管。为保证高产出，研究者开发了基于光刻技术的工艺流程，实现了晶圆级器件制备，展示了二维半导体在延续晶体管微缩路线中的可行性。","scd":{"b":9.0,"i":3.0,"r":8.0,"d":7.0,"t":6.0},"kp":["沟道长度[单层MoS₂晶体管]: <5 nm","亚阈值性能: 超越硅基本开关极限","IRDS预测硅沟道长度平台期: 12 nm(2037年)"]},{"i":66156,"as":"作者更正声明，涉及工业硅电池上稳定高性能钙钛矿/硅叠层太阳能电池界面设计策略研究的更正。","scd":{"b":4.0,"i":5.0,"r":2.0,"d":2.0,"t":3.0},"kp":[]},{"i":66157,"as":"三阴性乳腺癌（TNBC）多为p53突变、基底样转录程序的高级别浸润性导管癌，其中很大比例携带同源重组（HR）DNA修复缺陷的突变特征。本文发现携带复发性9p21.3–9p24扩增的基底样乳腺癌（BLBC），尤其是HR缺陷型，过表达RNA结合蛋白PUM3（Pumilio家族成员3）。在过表达PUM3的肿瘤细胞（包括BRCA1/BRCA2缺陷型）中，抑制PUM3表现出合成致死效应。机制上，PUM3通过抑制转录介导的复制应激和R-loop积累，防止HR缺陷细胞中本会发生的DNA损伤累积，从而维持肿瘤细胞适应性，提示PUM3是HR缺陷型乳腺癌的潜在治疗靶点。","scd":{"b":5.0,"i":2.0,"r":5.0,"d":6.0,"t":4.0},"kp":["PUM3表达[9p21.3–9p24扩增且HR缺陷的基底样乳腺癌]: 过表达","PUM3功能: 同源重组缺陷型乳腺癌中复制应激的关键抑制因子"]},{"i":66158,"as":"转录组全关联研究（TWAS）可将遗传位点与基因调控相关联，但传统的基于单SNP的模型忽略了变异之间的协同作用以及顺式片段的整体效应，导致因果基因定位能力受限。本文提出HapTWAS，一个单倍型分辨的TWAS分析框架。该框架以单倍型为单位建模，能够捕捉顺式区域内多个变异的组合调控作用，弥补传统SNP模型的信息损失，从而更准确地将遗传变异与基因表达及下游性状联系起来，为复杂性状的基因发现和机制解析提供了改进的工具。","scd":{"b":5.5,"i":3.0,"r":6.0,"d":5.0,"t":4.0},"kp":["框架类型: 单倍型分辨的全转录组关联研究(HapTWAS)","传统TWAS局限: 基于SNP的模型忽视变异间协同作用及顺式片段化"]},{"i":66159,"as":"再生神经发生需要在正确的位置产生正确类型的神经元以恢复组织结构与功能，但其遗传机制尚不清楚。涡虫具有出色的脑再生能力，其体内多能干细胞在损伤后可重新进行神经发生、重建复杂神经系统。本文以多巴胺能神经元身份为研究对象，发现了调控涡虫中枢、外周及咽部神经系统中该类神经元再生神经发生的关键因子，包括irx4/6、fliI-2、soxB等不同基因。研究表明组合式的基因调控机制在再生过程中同时决定细胞的空间位置与神经递质身份，为理解再生神经发生中神经元多样性和空间组织形式的产生提供了遗传学证据。","scd":{"b":5.5,"i":2.0,"r":5.0,"d":5.0,"t":4.0},"kp":["涡虫神经发生机制: 组合机制决定细胞位置和神经递质身份"]},{"i":66160,"as":"量子流体中湍流衰变的Kelvin波理论已存在数十年，但缺乏直接的实验验证。本文通过一个桌面尺度的经典水涡旋实验，观测到沿涡旋核心传播的Kelvin波湍流证据。实验测得的湍流能谱特征与理论预测相符，表明经典涡旋系统可以模拟量子流体中涡线上的Kelvin波级联与衰变过程。该结果为量子湍流衰变理论提供了实验支持，说明桌面尺度的经典流体实验可作为研究超流体量子湍动力学行为的有效平台。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":5.0,"t":5.0},"kp":["实验平台: 经典水涡旋桌面实验","验证内容: 沿涡旋核心Kelvin波湍流的实验证据，支持量子流体湍流衰变理论"]},{"i":66161,"as":"丰中子核⁴⁴S位于传统N=28壳层闭合减弱的区域，存在形状共存和大振幅集体运动，理解其形状混合的性质与程度是重要课题。本文通过单中子敲出反应测量⁴⁴S的谱因子，结合反应理论分析，探测其核形状信息。谱因子对单粒子轨道占据的敏感性使其可用于区分扁椭与长椭形状组态的混合程度，从而约束⁴⁴S的形状共存图像。该工作展示了单中子敲出反应结合谱因子分析在研究不稳定核形状结构中的应用价值。","scd":{"b":4.0,"i":1.5,"r":4.0,"d":4.0,"t":4.0},"kp":["研究方法: 单中子敲出反应谱因子探测","研究对象: 富中子核⁴⁴S的核形状共存"]},{"i":66162,"as":"α衰变半衰期对理解重核与超重核的稳定性和结构至关重要，在实验数据稀少的超重核区域，准确的半衰期预测尤为重要。本文基于神经网络建模开展了α衰变半衰期的系统学研究，构建了机器学习模型来描述α衰变半衰期与核结构参数之间的关系。通过训练已知核素的实验数据，模型实现了对半衰期的高精度预测，并被应用于超重核区域的系统计算。该工作展示了神经网络方法在核衰变性质预测中的有效性，为探索超重核稳定岛等实验难以覆盖的区域提供了理论工具。","scd":{"b":4.5,"i":2.0,"r":4.0,"d":5.0,"t":4.0},"kp":["方法: 基于神经网络建模的α衰变半衰期系统学研究","应用领域: 超重核稳定性研究"]},{"i":66163,"as":"本文开发了一种机器学习方法，通过融合多个全球核质量模型来校准核质量盈余预测。研究以AME2020中的已知核素为训练集，采用五个理论质量模型的预测结果作为输入，构建贝叶斯岭回归模型进行校准，实现了0.256 MeV的均方根误差，显著优于单一模型。校准后的质量盈余被进一步用于预测合成超重元素的聚变反应最佳入射能量，为超重元素合成实验提供了更可靠的理论指导。该方法展示了贝叶斯机器学习在核数据改进与实验参数优化中的应用价值。","scd":{"b":4.5,"i":2.0,"r":4.0,"d":6.0,"t":4.0},"kp":["模型: 贝叶斯岭回归校准核质量盈余预测","训练数据: AME2020已知核素+五个理论质量模型","均方根误差: 0.256 MeV"]},{"i":66164,"as":"光核数据库为核反应建模中的光子相互作用物理提供定量描述，支撑众多应用领域，但现有评估长期受实验测量与理论描述之间不一致性的限制。本文开发了用于光核反应的深度学习模拟器，并结合基于哈密顿蒙特卡洛的贝叶斯联合评估框架，对光核数据进行分析。该方法利用神经网络快速模拟反应观测量，通过哈密顿蒙特卡洛采样实现模型参数与实验数据不确定度的联合量化，从而系统性地整合实验与理论信息，改进光核数据评估的自洽性与精度，为核数据评估提供新的机器学习工具。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":7.0,"t":7.0},"kp":["[光核反应建模]: 深度学习模拟器结合哈密顿蒙特卡洛的贝叶斯联合评估框架","[现有光核数据库评估]: 受实验测量与理论描述间持续不一致限制"]},{"i":66165,"as":"本文报道了利用FAZIA阵列对62 MeV/核子下¹²C+¹²C反应前角碎裂微分截面开展的高精度测量。实验获得了Z=1至更大电荷数碎片的角分布数据，涵盖前角小角度区域。这些高质量微分截面数据可用于检验碎裂反应模型和输运理论，对核医学中碳离子治疗相关核数据以及空间辐射屏蔽研究具有应用价值。测量结果为理解中能重离子碰撞中碎裂机制及碎片产生提供了新的实验依据。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":7.0,"t":7.0},"kp":["碰撞能量[12C+12C碎裂]: 62 MeV/核子","测量对象[FAZIA阵列前角]: Z=1起碎裂微分截面，高精度角分布"]},{"i":66166,"as":"喷注内的能量-能量关联函数（EEC）是研究夸克-胶子等离子体中喷注修正的敏感观测量，但其在重离子碰撞中的解读需要一致地理解跨越多个动力学尺度的喷注演化。本文采用CoLBT-hydro模型研究了重离子碰撞中单喷注内的EEC。该模型将软共线辐射的线性玻尔兹曼输运与背景流体的流体动力学演化自洽耦合，能够统一描述喷注在介质中的能量损失与再辐射过程。研究给出了EEC对介质性质的响应特征，为利用EEC约束喷注淬火机制和介质输运参数提供了理论依据。","scd":{"b":5.0,"i":2.0,"r":5.0,"d":6.0,"t":7.0},"kp":["[重离子碰撞单喷注内能量-能量关联函数]: 采用CoLBT-hydro模型研究，是夸克胶子等离子体中喷注修正的敏感观测量"]},{"i":66167,"as":"准确预测弱快中子俘获（弱r过程）产生的元素丰度，需要对远离稳定线核素的核反应不确定度进行严格量化。本文在弱r过程模拟中，采用带不确定度量化的光学势截面，比较了两类中子俘获率变化的影响：独立的（非相关）率变化与通过底层光学势完全相关的率变化。结果表明，完全相关的变化会改变元素产额之间的协方差结构，而两类变化对最终元素丰度分布的影响存在差异。该工作为r过程核反应网络计算中的不确定度量化提供了系统方法。","scd":{"b":5.0,"i":2.0,"r":5.0,"d":6.0,"t":7.0},"kp":["[弱r过程元素丰度预测]: 需严格量化远离稳定线的中子俘获率不确定性，采用相关与非相关蒙特卡洛变化方法"]},{"i":66168,"as":"微管的结构完整性对细胞功能至关重要。本文对微管晶格断裂进行了理论分析，重点研究了由单体缺陷产生的多缝合线结构对断裂行为的影响，并旨在更准确地估计GDP态晶格参数。分析表明，缝合线作为晶格中的薄弱部位，在微管断裂过程中发挥关键作用，缺陷引起的多缝合线结构会显著改变断裂路径和力学响应。该工作超越了以往仅关注尖端动力学的视角，揭示了微管晶格层面断裂的内在机制，为理解微管的结构稳定性提供了新的理论认识。","scd":{"b":5.0,"i":1.5,"r":5.0,"d":5.0,"t":7.0},"kp":["[微管晶格断裂机制]: 理论分析单体缺陷引起的多缝合线结构影响，旨在更准确估计GDP-lattice参数"]},{"i":66169,"as":"边界处聚集是主动系统中普遍存在的现象，对微生物生态和工程应用均有意义。本文研究了通道内主动布朗粒子（ABP）的首达时间性质与空间分布，并基于Siegmund对偶性建立了理论分析框架。通过该对偶性，研究者获得了粒子到达通道边界的首达时间分布和稳态时空特性的解析结果，定量刻画了主动运动、通道约束与边界积累之间的关系。该工作为理解受限主动粒子系统的输运与聚集行为提供了严格的数学基础和物理洞察。","scd":{"b":5.0,"i":1.5,"r":5.0,"d":5.0,"t":7.0},"kp":["[通道中主动布朗粒子]: 基于Siegmund对偶性研究首达时间与时空分布特性"]},{"i":66170,"as":"非厄米光子学中的异常点可为拓扑光场调控提供奇异响应，但将奇异响应转化为对多个光学自由度的耦合控制仍是核心挑战。本研究基于等离激元非厄米超表面，在零本征值异常点处观测到矢量相位奇点，实现了异常点奇异响应对多光学自由度的耦合调控。该工作发表在《物理评论快报》（Phys. Rev. Lett. 137, 136601），为拓扑光场操控提供了新的物理机制与实现途径。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":7.0},"kp":["[矢量相位奇点]: 在零本征值异常点处的观测","[实现平台]: 等离激元非厄米超表面，实现多光学自由度的耦合调控"]},{"i":66171,"as":"积分电流涨落是统计力学领域长期关注的课题。近年来，以M-Wright函数刻画的反常电流涨落已在经典元胞自动机中被精确求解。本研究将这一结果推广至量子多体动力学，在量子多体系统中精确得到了反常电流涨落，其涨落分布同样由M-Wright函数描述。该成果发表于《物理评论快报》（Phys. Rev. Lett. 137, 136301），深化了对量子系统中输运涨落普适规律的理解。","scd":{"b":6.0,"i":1.5,"r":5.0,"d":5.0,"t":7.0},"kp":["[量子多体动力学反常电流涨落]: 积分电流涨落由M-Wright函数刻画并获得精确解"]},{"i":66172,"as":"自发性对称破缺是物理学核心组织原理之一。时间晶体作为自发破缺时间平移对称性的奇异物质相，通常被分为离散时间晶体和连续时间晶体两类。本研究提出“层级时间晶体”的新概念，将两种类型的时间晶体联系起来，构建了具有层级结构的时间晶体体系。该工作发表于《物理评论快报》（Phys. Rev. Lett. 137, 130402），拓展了时间晶体相的分类框架。","scd":{"b":6.5,"i":1.5,"r":5.0,"d":4.0,"t":7.0},"kp":["[时间晶体]: 提出兼具离散与连续类型特征的层级时间晶体，自发破缺时间平移对称"]},{"i":66173,"as":"基于HAL QCD合作组相同的NΩccc格点QCD势，此前不同计算对NNΩccc体系是否支持束缚态得出了相互矛盾的结论。本研究采用高度关联的指数变分法重新考察了该问题，对d-Ωccc体系（含NNΩccc）进行了精确变分计算。该工作发表于《物理评论C》（Phys. Rev. C 114, 034009），为澄清重子多体体系中束缚态的存在性问题提供了更可靠的计算方法。","scd":{"b":4.0,"i":1.5,"r":4.0,"d":5.0,"t":7.0},"kp":["[d-Ωccc体系研究方法]: 高度关联的指数变分法","[研究背景]: 基于同一HAL QCD协作组NΩccc格点QCD势的先前计算得出NNΩccc是否存在束缚态的矛盾结论"]},{"i":66174,"as":"山东能源集团贯彻国家煤炭工业“十五五”规划及能源强国战略，煤炭产量稳居全国前三，智能化建设走在行业前列。文章指出煤炭定位正从“主体能源”向“兜底保障”转变，即作为支撑能源安全、保障新能源消纳、提供基础化工原料的战略性兜底能源、灵活性调峰能源和基础性原料能源。集团提出以理念革新破局、布局优化固本、价值升级提质、生产迭代赋能、科技创新聚力，推动思想观念转型，重塑煤炭产业战略定位，走出根植主业、做强主业的煤炭产业高质量转型新路。","scd":{"b":1.0,"i":5.0,"r":4.0,"d":4.0,"t":7.0},"kp":[]}]);